  function northMarketWalletHTML(v){var data=v.data;return northMarketHeader('云端交易钱包')+'<div class="north-personal-scroll">'+(v.busy?'<div class="commerce-empty">正在读取云端余额…</div>':v.error?'<div class="commerce-empty">'+esc(v.error)+'<button class="btn p" onclick="northMarketWallet()">重试</button></div>':'<section class="north-merchant-card"><h3>我的美团云端余额</h3><h2>¥'+money(data.balance/100)+'</h2><p class="north-flow-muted">只用于小手机美团交易，不兑换人民币。</p>'+(!data.claimed?'<button class="btn p" onclick="northMarketClaim()">领取首次500虚拟币</button>':'<small>首次额度已领取，不限制经营收入或总余额。</small>')+'</section><section class="north-merchant-card"><h3>店铺已结算收入</h3><h2>¥'+money(data.income/100)+'</h2><div class="north-chips"><button onclick="northMarketTransferOpen(\'income\',\'wallet\')">转入本人美团余额</button>'+(northMarketCoupleRole()?'<button onclick="northMarketTransferOpen(\'income\',\'couple\')">转给情侣云银行卡</button>':'')+'</div><small>收入只在美团消费或转给情侣，不转入本机钱包或现实微信零钱。</small></section>'+(northMarketCoupleRole()&&data.couple?'<section class="north-merchant-card"><h3>'+esc(data.couple.name)+'的云银行卡</h3><h2>¥'+money(data.couple.balance/100)+'</h2>'+((data.couple.balance||0)<2000?'<p style="color:#e56b32">余额较低，可能不足以支付起送订单</p>':'')+'<div class="north-chips"><button onclick="northMarketTransferOpen(\'wallet\',\'couple\')">给情侣充值</button><button onclick="northMarketTransferOpen(\'couple\',\'wallet\')">转回本人美团余额</button></div></section>':'')+'<section class="north-merchant-card"><button class="btn g" onclick="northMarketCoupons()">我的真人店铺神券 ›</button><h3>最近云端资金记录</h3>'+(data.ledger||[]).map(function(row){return '<div class="north-check-line"><span>'+esc({grant:'首次赠送',purchase:'订单付款',refund:'退款',income:'店铺收入',withdraw:'收入转入美团',allocate:'情侣额度分配',admin_credit:'管理员发放'}[row.kind]||row.kind)+'<small>'+esc(fmtDT(row.created_at))+'</small></span><b>'+money(row.amount/100)+'</b></div>';}).join('')+'</section>')+'</div>';}
