  function northSpecGroupsHTML(p,cloud,kind){return (p.specGroups||[]).filter(function(g){return g.options.length&&(!kind||(kind==='cards')===(g.display==='cards'));}).map(function(g){var cards=g.display==='cards',selected=northSpecDefaults(p)[g.id]||[],attr=cloud?'data-market-group':'data-group',change=cloud?'northMarketSpecChange()':'northMerchantSelection('+northMarketArgument(g.id)+')';return '<section class="north-spec-section '+(cards?'north-spec-card-group':'')+'"><h4>'+esc(g.name)+'</h4>'+(g.subtitle?'<small class="north-spec-hint">'+esc(g.subtitle)+'</small>':cards?'<small class="north-spec-hint">'+(g.required?'请选择':'可不选')+' · '+(g.mode==='multiple'?'每种一份／'+esc(p.unit):'单选')+'</small>':'')+'<div class="'+(cards?'north-extra-grid':'north-chips')+'">'+g.options.map(function(o){var price=g.totalPrice?' · ¥'+money((p.price+o.price)/100).replace(/\.00$/,''):o.price?' +¥'+money(o.price/100).replace(/\.00$/,''):'',media=cards&&o.image?'<span class="north-option-media">'+(cloud?northMarketImage(o.image,o.label):mtMedia({name:o.label,imageUrl:o.image}))+'</span>':'';return '<label class="north-custom-option '+(cards?'north-addon-choice ':'')+(selected.includes(o.id)?'on':'')+'"><input type="'+(g.mode==='single'?'radio':'checkbox')+'" name="'+(cloud?'north_market_':'north_spec_')+northMarketAttr(g.id)+'" '+attr+'="'+northMarketAttr(g.id)+'" value="'+northMarketAttr(o.id)+'" '+(selected.includes(o.id)?'checked':'')+' onchange="'+change+'">'+media+'<span>'+esc(o.label)+(cards?(o.recommended?'<small class="north-extra-recommend">推荐</small>':'')+'<small>'+esc(price.trim()||'不加价')+'</small>':esc(price)+(o.recommended?'<small class="north-extra-recommend">推荐</small>':''))+'</span></label>';}).join('')+'</div>'+(!g.required?'<button class="north-spec-clear" type="button" onclick="'+(cloud?'northMarketSpecClear(':'northMerchantClearSelection(')+northMarketArgument(g.id)+')">不选／清空</button>':'')+'</section>';}).join('');}
  function northSpecDialogHTML(p,cloud,live,shop){var quantity=cloud?'north_market_quantity':'north_custom_qty',change=cloud?'northMarketSpecChange()':'northMerchantSpecPrice()',add=cloud?'northMarketAdd()':'northMerchantAddLine()',action=cloud?'northMarketSpecAction':'northMerchantQuickAction',couple=cloud&&!northMarketCoupleRole(),favorite=cloud?northFavoriteButton('product','cloud',shop.id+'~'+p.id):live?northFavoriteButton('product','custom',p.id):'';return '<div class="north-flow north-spec north-custom-specs north-spec-layout"><header class="north-spec-heading"><h3>'+northSignatureBadge(!!p.signature)+esc(p.name)+'</h3>'+favorite+'</header><div class="north-spec-scroll">'+northSpecGroupsHTML(p,cloud,'chips')+'<label class="north-spec-quantity">数量<input id="'+quantity+'" type="number" min="1" max="'+(cloud?Math.min(20,p.stock):20)+'" step="1" value="1" oninput="'+change+'"></label>'+northSpecGroupsHTML(p,cloud,'cards')+'<div class="north-selected-spec" id="'+(cloud?'north_market_selected':'north_custom_selected')+'"></div></div><footer class="north-spec-bottom"><div class="north-spec-primary"><b class="north-spec-price '+(!cloud?'north-custom-price':'')+'" '+(cloud?'id="north_market_spec_price"':'')+'>¥'+money(p.price/100)+'</b><button '+(cloud?'id="north_market_spec_add"':'data-custom-add')+' onclick="'+add+'" '+(!live?'disabled':'')+'>＋ 加入购物车</button></div><div class="north-shortcuts"><button data-spec-action="gift" onclick="'+action+'(\'gift\')" '+(!live||couple?'disabled':'')+'>我给角色点</button><button data-spec-action="pay" onclick="'+action+'(\'pay\')" '+(!live||couple?'disabled':'')+'>让角色代付</button></div>'+(!live?'<small class="north-spec-hint">保存并开店后才能下单</small>':'')+'</footer></div>';}
  window.northMarketSpecAction=async function(action){if(!['gift','pay'].includes(action)||northSaving||northMarketBusy)return;if(!northMarketCoupleRole()){toast('请先设置当前情侣，才能赠餐或使用情侣云银行卡代付');return;}var draft=northMarketSpecDraft;if(!draft||!draft.quote||draft.account!==actId())return;var role=northMarketCoupleRole(),ok=await northMarketAdd();if(!ok||actId()!==draft.account||northMarketCoupleRole()!==role)return;await northMarketCheckout();var pay=northMarketPayDraft;if(!pay||pay.account!==draft.account||pay.quote.shopId!==draft.shop.id||northMarketCoupleRole()!==role)return;if(action==='gift')northMarketGiftSelect();else {northMarketFunding('role');northMarketPaymentMethods();}};
  window.northMarketSpecs=function(id){var v=northMarketView,p=v&&v.products&&v.products.find(function(p){return p.id===id;});if(!p||v.account!==actId()||northMarketBusy)return;if(p.soldOut||p.stock===0){toast('商品已卖完，请等商家补货');return;}northMarketSpecDraft={account:actId(),shop:v.shop,product:p,selections:northSpecDefaults(p)};openModal(northSpecDialogHTML(p,true,true,v.shop));northMarketSpecChange();};
  window.northMarketSpecClear=function(id){var d=northMarketSpecDraft,g=d&&d.product.specGroups.find(function(g){return g.id===id;});if(!g||g.required||d.account!==actId())return;Array.from(document.querySelectorAll('[data-market-group]')).filter(function(input){return input.dataset.marketGroup===id;}).forEach(function(input){input.checked=false;});northMarketSpecChange();};
  window.northMarketSpecChange=function(){var d=northMarketSpecDraft,quantity=document.getElementById('north_market_quantity');if(!d||d.account!==actId()||!quantity)return;d.product.specGroups.forEach(function(g){d.selections[g.id]=Array.from(document.querySelectorAll('[data-market-group]:checked')).filter(function(input){return input.dataset.marketGroup===g.id;}).map(function(input){return input.value;});});d.quantity=+quantity.value;d.quote=northMerchantQuote(d.product,d.selections,d.quantity);var target=document.getElementById('north_market_spec_price');if(target)target.textContent=d.quote?'¥'+money(d.quote.total/100):'请选择有效规格和数量';var selected=document.getElementById('north_market_selected'),add=document.getElementById('north_market_spec_add');if(selected)selected.textContent='已选规格：'+(d.quote?d.quote.labels.concat([d.quantity+' '+d.product.unit]).join('、'):'请选择必选规格');if(selected)selected.hidden=!!d.quote;if(add)add.disabled=!d.quote||d.quantity>d.product.stock;document.querySelectorAll('#modal [data-spec-action]').forEach(function(button){button.disabled=!d.quote||d.quantity>d.product.stock||!northMarketCoupleRole();});northSpecPaint();};
  window.northMarketAdd=async function(){var d=northMarketSpecDraft;if(northSaving||northMarketBusy||!d||d.account!==actId()||!d.quote)return;if(typeof NORTH_PREVIEW!=='undefined'&&NORTH_PREVIEW&&!/^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname)){toast('免邀请码预览不能提交真人订单；请在正式账号中结算或给情侣点餐');return false;}var cart=S.food.cart=S.food.cart||[],item={name:d.product.name,price:d.quote.total/100,quantity:d.quantity,unit:d.product.unit,imageUrl:d.product.image,shop:d.shop.name,_northAccount:actId(),_northMarket:d.shop.id,_northMarketMinimum:d.shop.minimum,_northMarketDelivery:d.shop.delivery,_northProduct:d.product.id,_northRevision:d.shop.revision,_northSelections:JSON.parse(JSON.stringify(d.selections)),_northLabels:d.quote.labels.slice(),_northSignature:!!d.product.signature,_northRow:uid()};if(northMarketCartRows(d.shop.id).length>=20){toast('每笔真人订单最多20行商品');return;}var ok=await northCommit(function(){cart.push(item);return function(){var index=cart.indexOf(item);if(index>=0)cart.splice(index,1);};});if(ok&&actId()===d.account){northMarketSpecDraft=null;closeModal();render();mtPaintCart();toast('已加入真人店铺购物车');}return !!(ok&&actId()===d.account);};
  window.northMarketCart=function(){var v=northMarketView;if(!v||!v.shop)return;var rows=northMarketCartRows(v.shop.id),sum=rows.reduce(function(n,p){return n+northCents(p.price);},0);openModal('<div class="north-flow north-merchant-form"><h3>'+esc(v.shop.name)+' · 购物车</h3>'+rows.map(function(p){return '<div class="north-cart-row"><div><b>'+esc(p.name)+'</b><small>'+esc((p._northLabels||[]).join('／'))+' · ×'+p.quantity+'</small></div><b>¥'+money(p.price)+'</b><button onclick="northMarketRemove(\''+p._northRow+'\')">移除</button></div>';}).join('')+'<p>商品合计 ¥'+money(sum/100)+' · ¥'+money(v.shop.minimum/100)+'起送</p><button class="btn p" onclick="northMarketCheckout()" '+(sum<v.shop.minimum||!rows.length?'disabled':'')+'>'+(sum<v.shop.minimum?'还差 ¥'+money((v.shop.minimum-sum)/100):'去结算')+'</button><button class="btn g" onclick="closeModal()">继续选商品</button></div>');};
  window.northMarketRemove=async function(id){if(northSaving||northMarketBusy)return;var cart=S.food.cart||[],item=cart.find(function(p){return p._northRow===id&&p._northAccount===actId()&&p._northMarket;});if(!item)return;if(northMarketSplitInvites().some(function(e){return e.account===actId()&&e.status==='pending'&&e.snapshot.rows.includes(id);})){toast('这件商品正在拼单，请先取消拼单或核对付款结果');return;}var index=cart.indexOf(item),ok=await northCommit(function(){cart.splice(index,1);return function(){cart.splice(index,0,item);};});if(ok){render();northMarketCart();}};
  window.northMarketCheckout=async function(){var v=northMarketView;if(northMarketBusy||!v||!v.shop)return;var rows=northMarketCartRows(v.shop.id);if(!rows.length){toast('请先选商品');return;}var invitation=northMarketSplitInvites().find(function(e){return e.account===actId()&&['pending','paid'].includes(e.status)&&e.snapshot.rows.some(function(id){return rows.some(function(p){return p._northRow===id;});});});if(invitation)return northMarketResumeSplit(invitation);var prior=northMarketTransactions().find(function(t){return t.account===actId()&&['pending','unknown','paid'].includes(t.status)&&t.snapshot&&t.snapshot.rows.some(function(id){return rows.some(function(p){return p._northRow===id;});});});if(prior)return northMarketResumeTransaction(prior);var account=actId(),state=S,lines=rows.map(function(p){return {productId:p._northProduct,quantity:p.quantity,selections:p._northSelections||{}};});if(rows.some(function(p){return p._northRevision!==v.shop.revision;})){toast('商品价格或规格已经更新，请重新选购');return;}northMarketBusy=true;try{await northMarketEnsure();var quote=await northMarketRpc('quote',{p_id:v.shop.id,p_revision:v.shop.revision,p_lines:lines}),wallet=await northMarketSyncCouple();if(account!==actId()||state!==S)return;var address=northData().addresses&&northData().addresses[account]||{},draft={account:account,state:state,quote:quote,lines:lines,rows:rows.map(function(p){return p._northRow;}),client:crypto.randomUUID(),roleId:'',wallet:wallet,shipping:{address:address.address||'小手机 · 我的家',name:address.receiver||S.me.name||'我',phone:address.phone||'',note:address.note||''},utensils:null};northMarketPayDraft=draft;northMarketView={page:'checkout',account:account,draft:draft};closeModal();render();}catch(error){toast(error.message);}finally{northMarketBusy=false;}};
  function northMarketCheckoutHTML(v){var d=v.draft,q=d.quote;return '<div class="north-checkout-page"><header class="north-checkout-top"><button onclick="northMarketCheckoutBack()" aria-label="返回店铺">'+mtGlyph('chevronLeft',24,'currentColor')+'</button><b>确认订单</b></header><div class="north-checkout-scroll"><section class="north-checkout-card"><h3>外卖配送</h3><label>收货位置<input id="north_market_address" maxlength="200" value="'+northMarketAttr(d.shipping.address)+'"></label><label>收货称呼<input id="north_market_receiver" maxlength="40" value="'+northMarketAttr(d.shipping.name)+'"></label><label>联系电话<input id="north_market_phone" maxlength="30" value="'+northMarketAttr(d.shipping.phone)+'"></label><button class="north-address-choice" onclick="northMarketAddressPick()">选择已保存的收货地址 ›</button><div class="north-delivery-options"><b>标准配送<small>按店铺时长自动配送</small></b><button onclick="northScheduleOpen(true)">预约配送<small>'+esc(d.scheduledAt?fmtDT(d.scheduledAt):'选择送达时间')+'</small></button></div></section><section class="north-checkout-card"><h4>'+esc(q.shopName)+'</h4>'+q.items.map(function(p){return '<div class="north-check-product"><span class="north-sale-thumb">'+northMarketImage(p.image,p.name)+'</span><div><b>'+northSignatureBadge(p.signature)+esc(p.name)+'</b><small>'+esc(p.labels.join('／'))+' · ×'+p.quantity+'</small></div><strong>¥'+money(p.total/100)+'</strong></div>';}).join('')+'<div class="north-check-line"><span>商品原价</span><b>¥'+money(q.subtotal/100)+'</b></div><div class="north-check-line"><span>打包费</span><b>¥0.00</b></div><div class="north-check-line"><span>配送费</span><b>¥'+money(q.delivery/100)+'</b></div><button class="north-check-line north-coupon-entry" onclick="northMarketChooseCoupon()"><span>云端神券</span><small>'+(q.discount?'−¥'+money(q.discount/100):'选择优惠券')+' ›</small></button></section><section class="north-checkout-card"><div class="north-shortcuts"><button onclick="northMarketCheckoutRolePay()">让角色代付</button><button onclick="northMarketGiftSelect()">我给角色点</button></div><label>订单备注<textarea id="north_market_note" maxlength="200" placeholder="口味与包装要求">'+esc(d.shipping.note)+'</textarea></label><button class="north-check-line north-funding-choice" onclick="northMarketPaymentMethods()"><span>付款方式</span><b>'+esc(d.roleId?'情侣云银行卡':'本人美团云端钱包')+' ›</b></button>'+(d.giftId?'<p>送给'+esc(d.giftName)+'</p>':'')+'<button class="north-check-line north-funding-choice" onclick="northMarketSplitPick()"><span>邀请真人好友一起拼单</span><small>双方各付一半 ›</small></button></section><p class="north-flow-muted">真人店铺不支持亲属卡；使用云端虚拟币，新订单到预计时间自动完成并结算。</p></div><footer class="north-checkout-paybar"><b>¥'+money(q.total/100)+'</b><button onclick="northMarketPay()">立即支付</button></footer></div>';}
  function northMarketCaptureShipping(){var d=northMarketPayDraft,address=document.getElementById('north_market_address');if(!d||!address||d.lockedRequest)return;var receiver=document.getElementById('north_market_receiver'),phone=document.getElementById('north_market_phone'),note=document.getElementById('north_market_note');d.shipping={address:address.value.trim(),name:receiver.value.trim(),phone:phone.value.trim(),note:note.value.trim()};}
  window.northMarketCheckoutBack=function(){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy)return;northMarketCaptureShipping();northMarketOpen(d.quote.shopId);};
  window.northMarketCheckoutRolePay=function(){var d=northMarketPayDraft;if(!d||d.account!==actId()||northMarketBusy)return;if(!northMarketCoupleRole()){toast('请先设置当前情侣，才能使用情侣云银行卡代付');return;}northMarketPaymentMethods();};
  window.northMarketAddressPick=function(){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy||d.lockedRequest)return;northMarketCaptureShipping();var rows=northPersonalData().addresses;openModal('<div class="north-flow"><h3>选择收货地址</h3>'+rows.map(function(a){return '<button class="btn g" onclick="northMarketAddressChoose('+northMarketArgument(a.id)+')">'+esc(a.address)+'<small>'+esc(a.receiver)+' '+esc(northPhoneMask(a.phone))+'</small></button>';}).join('')+(!rows.length?'<p>暂无保存的地址，可以返回订单直接填写。</p>':'')+'<button class="btn p" onclick="closeModal()">返回订单</button></div>');};
  window.northMarketAddressChoose=function(id){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy||d.lockedRequest)return;var a=northPersonalData().addresses.find(function(a){return a.id===id;});if(!a)return;d.shipping=Object.assign({},d.shipping,{address:a.address,name:a.receiver,phone:a.phone||''});closeModal();render();};
  function northMarketProgress(o){var stage={paid:0,accepted:1,ready:2,delivered:3,completed:3,cancelled:-1}[o.status];if(stage==null)stage=-1;var auto=!!o.auto_delivery_at;var hint={paid:'小袋鼠等待店主接单',accepted:'店主正在制作餐品',ready:'小袋鼠配送中',delivered:'小袋鼠已送达，等待确认收货',completed:'本单已完成',cancelled:'本次配送已取消'}[o.status]||'请刷新核对订单状态';if(auto&&o.status==='paid')hint='小袋鼠准备餐品中';var title={paid:auto?'准备中':'待接单',accepted:'制作中',ready:'配送中',delivered:'已送达',completed:'已完成',cancelled:'已取消'}[o.status]||'待核对';return '<div class="north-eta-row"><strong class="north-order-eta">'+esc(title)+'</strong><small class="north-eta-label">'+(o.auto_delivery_at?'预计 '+esc(fmtDT(Date.parse(o.auto_delivery_at))):o.scheduled_at?'预约 '+esc(fmtDT(Date.parse(o.scheduled_at))):'标准配送')+'</small></div><h3 class="north-order-headline">'+esc(auto&&o.status==='paid'?'已付款，等待自动制作配送':auto&&o.status==='ready'?'小袋鼠配送中，到时间自动完成':auto&&o.status==='completed'?'外卖已送达，本单已完成':northMarketStatus(o.status))+'</h3><div class="north-delivery-track"><i style="width:'+Math.max(0,stage)*33.333+'%"></i>'+['付款','制作','配送','送达'].map(function(text,i){return '<span class="north-track-node '+(stage>=i?'on':'')+'" data-step="'+i+'"><b>'+(i===3?'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4 10-10"/></svg>':mtGlyph(i===0?'ticket':i===1?'order':'cart',19,'currentColor'))+'</b><small>'+text+'</small></span>';}).join('')+'</div>'+northMap(o,{stage:stage,hint:hint,disclaimer:'配送示意地图 · 非现实定位'})+'<p class="north-order-explainer">'+(auto?'按订单预计时间自动完成并结算，云端每分钟处理一次。':'旧订单由店主接单、制作发货，买家确认收货后完成。')+'地图按云端订单状态展示。</p>';}
  window.northMarketPaymentMethods=function(){var d=northMarketPayDraft;if(!d||d.account!==actId()||northMarketBusy)return;if(d.lockedRequest){toast('正在核对上一笔付款结果，付款来源暂时不能更改');return;}northMarketCaptureShipping();var role=northMarketCoupleRole(),available=d.wallet.couple&&d.wallet.couple.balance||0;openModal('<div class="north-flow north-merchant-form"><h3>选择付款方式</h3><div class="north-chips"><button onclick="northMarketFunding(\'wallet\')" class="'+(!d.roleId?'on':'')+'">本人美团云端钱包 · ¥'+money(d.wallet.balance/100)+'</button>'+(role&&d.wallet.couple&&d.wallet.couple.id===role.id?'<button onclick="northMarketFunding(\'role\')" class="'+(d.roleId?'on':'')+'" '+(available<d.quote.total?'disabled':'')+'>让'+esc(role.remark||role.name||'情侣')+'代付 · 云银行卡 ¥'+money(available/100)+'</button>'+(available<d.quote.total?'<p style="color:#e66b32">情侣云银行卡余额不足，还差 ¥'+money((d.quote.total-available)/100)+'</p><button class="btn g" onclick="northMarketTransferOpen(\'wallet\',\'couple\')">给情侣充值</button>':''):'<p class="north-flow-muted">只有当前情侣可以代付真人店铺订单。</p>')+'</div><button class="btn g" onclick="closeModal()">返回订单</button></div>');};
  window.northMarketFunding=function(mode){var d=northMarketPayDraft;if(!d||d.account!==actId()||northMarketBusy)return;if(mode!=='wallet'&&mode!=='role'){toast('真人店铺不支持这种付款方式');return;}var role=northMarketCoupleRole();if(mode==='role'&&(!role||!d.wallet.couple||d.wallet.couple.id!==role.id||d.wallet.couple.balance<d.quote.total)){toast('当前情侣云银行卡不可用于付款，请先充值');return;}d.roleId=mode==='role'?role.id:'';closeModal();render();};
  window.northMarketPay=function(){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy)return;northMarketCaptureShipping();if(!d.shipping.address||!d.shipping.name){toast('请填写收货地址和称呼');return;}d.utensils=null;northMarketPin='';openModal('<div class="north-flow north-utensils"><button class="north-flow-close" onclick="closeModal()" aria-label="关闭">×</button><p>'+esc(d.shipping.address)+'<br><small>'+esc(d.shipping.name)+'</small></p><h3>当前地址下单，是否需要餐具？</h3><div class="north-utensil-options"><button onclick="northMarketUtensils(true)">需要餐具</button><button onclick="northMarketUtensils(false)">无需餐具<small>轻装出发</small></button></div><button class="btn p" id="north_market_utensil_save" onclick="northMarketUtensilSave()" disabled>保存并继续</button></div>');};
  window.northMarketUtensils=function(value){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy||typeof value!=='boolean')return;d.utensils=value;document.querySelectorAll('.north-utensil-options button').forEach(function(button,i){button.classList.toggle('on',(i===0)===value);});var save=document.getElementById('north_market_utensil_save');if(save)save.disabled=false;};
  window.northMarketUtensilSave=function(){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy||typeof d.utensils!=='boolean'||!document.getElementById('north_market_utensil_save'))return;if(d.roleId){northMarketRequestCouple();return;}northMarketPinOpen();};
  function northMarketPinOpen(){var d=northMarketPayDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy)return;northMarketPin='';openModal('<div class="north-flow north-password"><button class="north-flow-close" onclick="closeModal()" aria-label="关闭支付">×</button><p>'+esc(d.quote.shopName)+'</p><h2>¥'+money(d.quote.total/100)+'</h2><div class="north-check-line"><span>付款方式</span><b>'+esc(d.roleId?'情侣云银行卡':'本人美团云端钱包')+'</b></div><div class="north-password-dots" aria-label="五位支付密码">'+[0,1,2,3,4].map(function(){return '<span></span>';}).join('')+'</div><p class="north-password-error" id="north_market_pin_error" aria-live="polite">请输入五位云端支付密码</p><div class="north-keypad">'+['1','2','3','4','5','6','7','8','9','cancel','0','delete'].map(function(key){return '<button data-market-digit="'+key+'" onclick="northMarketPinKey(\''+key+'\')" aria-label="'+(key==='delete'?'删除一位':key==='cancel'?'取消支付':key)+'">'+(key==='delete'?'⌫':key==='cancel'?'取消':key)+'</button>';}).join('')+'</div></div>');}
  window.northMarketPinKey=function(key){if(northMarketBusy)return;if(key==='cancel'){northMarketPin='';closeModal();return;}if(key==='delete')northMarketPin=northMarketPin.slice(0,-1);else if(/^\d$/.test(key)&&northMarketPin.length<5)northMarketPin+=key;document.querySelectorAll('.north-password-dots>span').forEach(function(el,i){el.textContent=i<northMarketPin.length?'●':'';});if(northMarketPin.length===5)northMarketSubmitOrder(northMarketPin);};
  function northMarketRequests(){var data=northData();data.marketRequests=data.marketRequests||[];return data.marketRequests;}
  window.northMarketRequestCouple=async function(){var d=northMarketPayDraft,c=northMarketCoupleRole();if(northSaving||northMarketBusy||!d||d.account!==actId()||d.state!==S||!c||c.id!==d.roleId)return;if(northMarketRequests().some(function(r){return r.account===d.account&&r.roleId===c.id&&['pending','approved'].includes(r.status)&&r.expiresAt>Date.now();})){toast('请先处理情侣上一笔云端代付请求');return;}var request={id:d.client,account:d.account,roleId:c.id,status:'pending',expiresAt:Date.now()+15*60000,draft:{account:d.account,quote:JSON.parse(JSON.stringify(d.quote)),lines:JSON.parse(JSON.stringify(d.lines)),rows:d.rows.slice(),client:d.client,roleId:d.roleId,wallet:JSON.parse(JSON.stringify(d.wallet)),shipping:Object.assign({},d.shipping),utensils:d.utensils,couponId:d.couponId||null,scheduledAt:d.scheduledAt||null}},message={id:uid(),time:Date.now(),role:'user',type:'paycard',northRequestId:request.id,marketRequestId:request.id,price:d.quote.total/100,name:d.quote.items.map(function(p){return p.name;}).join('、'),shop:d.quote.shopName};var ok=await northCommit(function(){northMarketRequests().push(request);pushMsg(c.id,message);return function(){var i=northMarketRequests().indexOf(request);if(i>=0)northMarketRequests().splice(i,1);var messages=msgs(c.id),j=messages.indexOf(message);if(j>=0)messages.splice(j,1);};});if(ok&&c===northMarketCoupleRole()&&actId()===d.account){d.roleRequest=request.id;closeModal();toast('已向情侣发送云银行卡代付请求，尚未扣款');scheduleReply(c.id);northMarketRequestOpen(c.id,request.id);}};
  function northMarketRequestValid(request){var c=northMarketCoupleRole();return !!(request&&request.account===actId()&&c&&c.id===request.roleId&&request.expiresAt>Date.now()&&msgs(c.id).some(function(m){return m.role==='user'&&m.type==='paycard'&&m.northRequestId===request.id&&!m.recalled&&!m._rejected;}));}
  window.northMarketRequestOpen=function(cid,id){var r=northMarketRequests().find(function(r){return r.id===id&&r.account===actId()&&r.roleId===cid;});if(!r)return;openModal('<div class="north-flow north-merchant-form"><h3>情侣云银行卡代付</h3><p>'+esc(r.draft.quote.shopName)+' · '+esc(r.draft.quote.items.map(function(p){return p.name;}).join('、'))+'</p><h2>¥'+money(r.draft.quote.total/100)+'</h2>'+r.draft.quote.items.map(function(p){return '<p>'+esc(p.labels.join('／'))+' · ×'+p.quantity+'</p>';}).join('')+'<p>状态：'+esc({pending:'等待情侣决定',approved:'情侣已同意，等待支付密码确认',paid:'云端已付款',rejected:'情侣已拒绝',cancelled:'已取消',failed:'未完成'}[r.status]||r.status)+'</p>'+(r.status==='approved'&&northMarketRequestValid(r)?'<button class="btn p" onclick="northMarketRoleContinue(\''+r.id+'\')">继续确认云端支付</button>':'')+(['pending','approved'].includes(r.status)?'<button class="btn g" onclick="northMarketRequestCancel(\''+r.id+'\')">取消请求</button>':'')+'<button class="btn g" onclick="closeModal()">关闭</button></div>');};
  window.northMarketRequestCancel=async function(id){var r=northMarketRequests().find(function(r){return r.id===id&&r.account===actId();});if(!r||northSaving||northMarketBusy||!['pending','approved'].includes(r.status))return;var previous=r.status,ok=await northCommit(function(){r.status='cancelled';return function(){r.status=previous;};});if(ok){var message=msgs(r.roleId).find(function(m){return m.northRequestId===id;});if(message)message._rejected=true;closeModal();toast('请求已取消，未扣款');}};
  window.northMarketRoleContinue=function(id){var r=northMarketRequests().find(function(r){return r.id===id&&r.account===actId();});if(!r||r.status!=='approved'||!northMarketRequestValid(r)){toast('情侣关系或请求已失效');return;}northMarketPayDraft=Object.assign(JSON.parse(JSON.stringify(r.draft)),{state:S,roleApproved:true,roleRequest:r.id});northMarketPinOpen();};
  async function northMarketRoleDecision(c,id,reject){var r=northMarketRequests().find(function(r){return r.id===id&&r.account===actId()&&r.roleId===c.id;});if(!r)return false;if(r.status==='paid'||r.status==='approved')return true;if(r.status!=='pending'||!northMarketRequestValid(r))return false;var before=r.status,account=actId(),ok=await northCommit(function(){r.status=reject?'rejected':'approved';return function(){r.status=before;};});if(!ok||account!==actId()||c!==northMarketCoupleRole())return false;if(reject){var message=msgs(c.id).find(function(m){return m.northRequestId===id;});if(message)message._rejected=true;save();}else toast('情侣已同意，请在代付卡片中继续确认支付密码');return true;}
  function northMarketRoleCard(c,m){mtStyles();var r=northMarketRequests().find(function(r){return r.id===m.marketRequestId&&r.account===actId();});if(!r)return '';var q=r.draft.quote;return '<article class="wx-north-food-card light"><header><b>'+northNavIcon('my')+' 真人店铺外卖</b><span>'+esc({pending:'等待代付',approved:'已同意 · 待确认',paid:'已付款',rejected:'已拒绝',cancelled:'已取消',failed:'未完成'}[r.status]||r.status)+'</span></header>'+northCompactOrderItems({items:q.items,shop_name:q.shopName})+'<div class="wx-north-food-total"><small>含配送费 · 情侣云银行卡</small><b>¥'+money(q.total/100)+'</b></div><footer><span>云端订单 · 未使用本机银行余额</span><button onclick="event.stopPropagation();northMarketRequestOpen(\''+c.id+'\',\''+r.id+'\')">查看详情 ›</button></footer></article>';}
  function northMarketGiftCard(c,m){mtStyles();var d=m.marketGiftDetail;if(!d||d.account!==actId())return '';return '<article class="wx-north-food-card light"><header><b>'+northNavIcon('my')+' 我给'+esc(c&&(c.remark||c.name)||'角色')+'点</b><span>云端已下单</span></header>'+northCompactOrderItems({items:d.items,shop_name:d.shop})+'<div class="wx-north-food-total"><small>实际云端付款</small><b>¥'+money(d.total/100)+'</b></div><footer><span>到预计时间自动完成</span><button onclick="event.stopPropagation();northMarketOrder(\''+m.marketGiftOrderId+'\')">订单详情 ›</button></footer></article>';}
  window.NorthMarket={card:northMarketRoleCard,giftCard:northMarketGiftCard,giftMessageText:function(m){var d=m.marketGiftDetail;return d&&d.account===actId()?'[我在真人用户店铺'+d.shop+'给你点了'+d.items.map(function(p){return p.name+'('+p.labels.join('／')+'，'+p.quantity+'份)';}).join('、')+'，已从美团云端资金支付'+money(d.total/100)+'虚拟币。你可以自然回应这份心意；到云端预计送达时间并显示已完成之前，不要宣称已经送到或吃上。不要用本机模拟收外卖/退款标签改变这笔云端订单。]':'[云端外卖记录]';}};
  window.northMarketGiftSelect=function(){var d=northMarketPayDraft,c=northMarketCoupleRole();if(!d||d.account!==actId()||northMarketBusy||!c||d.lockedRequest){toast('只有当前情侣可以接收真人店铺赠餐');return;}northMarketCaptureShipping();d.giftId=c.id;d.giftName=c.remark||c.name||'情侣';d.roleId='';render();toast('这笔订单送给情侣，由本人美团云端资金支付');};
  function northMarketTransactions(){var d=northData();d.marketTransactions=d.marketTransactions||[];return d.marketTransactions;}
  function northMarketTransactionSnapshot(d){return {account:d.account,quote:JSON.parse(JSON.stringify(d.quote)),lines:JSON.parse(JSON.stringify(d.lines)),rows:d.rows.slice(),client:d.client,roleId:d.roleId,wallet:JSON.parse(JSON.stringify(d.wallet)),shipping:Object.assign({},d.shipping),utensils:d.utensils,roleApproved:!!d.roleApproved,roleRequest:d.roleRequest||null,couponId:d.couponId||null,giftId:d.giftId||null,giftName:d.giftName||'',scheduledAt:d.scheduledAt||null};}
  async function northMarketResumeTransaction(transaction){if(northMarketBusy||transaction.account!==actId())return;northMarketBusy=true;try{await northMarketEnsure();var wallet=await northMarketSyncCouple();if(transaction.snapshot.wallet.accountKey&&wallet.accountKey!==transaction.snapshot.wallet.accountKey)throw Error('这笔待确认交易属于另一个授权账户，不会从当前账户扣款');var d=Object.assign(JSON.parse(JSON.stringify(transaction.snapshot)),{state:S,lockedRequest:true});var found=await northMarketRpc('orders',{p_seller:false,p_client:d.client},true);if(found.orders&&found.orders.length){await northMarketApplyOrder(d,found.orders[0]);return;}if(transaction.status==='paid')throw Error('已付款记录需要核对，请从真人订单查看');northMarketPayDraft=d;northMarketView={page:'checkout',account:actId(),draft:d};closeModal();render();toast('上一笔付款结果尚未确认，继续支付会使用同一订单编号');}catch(error){toast(error.message);}finally{northMarketBusy=false;}}
  async function northMarketApplyOrder(d,order){if(d.account!==actId()||d.state!==S)return false;var transaction=northMarketTransactions().find(function(t){return t.client===d.client&&t.account===d.account;});if(transaction){transaction.status='paid';transaction.orderId=order.id;}S.food.cart=(S.food.cart||[]).filter(function(p){return !d.rows.includes(p._northRow);});if(d.roleRequest){var request=northMarketRequests().find(function(r){return r.id===d.roleRequest&&r.account===d.account;});if(request)request.status='paid';var message=msgs(d.roleId).find(function(m){return m.northRequestId===d.roleRequest;});if(message)message._paid=true;if(!msgs(d.roleId).some(function(m){return m.type==='paid'&&m.marketRequestId===d.roleRequest;}))pushMsg(d.roleId,{id:uid(),time:Date.now(),role:'assistant',type:'paid',marketRequestId:d.roleRequest,price:order.total/100,name:order.items.map(function(p){return p.name;}).join('、'),shop:order.shop_name});}if(d.giftId&&northMarketCoupleRole()&&northMarketCoupleRole().id===d.giftId&&!msgs(d.giftId).some(function(m){return m.marketGiftOrderId===order.id;}))pushMsg(d.giftId,{id:uid(),time:Date.now(),role:'user',type:'marketgift',marketGiftOrderId:order.id,marketGiftDetail:{account:d.account,items:order.items,shop:order.shop_name,total:order.total}});var localSaved=true;try{await saveNowAsync();}catch(_){localSaved=false;}if(localSaved&&d.giftId&&northMarketCoupleRole()&&northMarketCoupleRole().id===d.giftId)scheduleReply(d.giftId);northMarketPayDraft=null;northMarketWalletCache=null;closeModal();northMarketBusy=false;await northMarketOrder(order.id);toast(localSaved?'云端付款成功，订单已提交给店主':'云端付款已完成，本机记录保存失败；可在真人订单中查看');return true;}
  var northMarketOrigin=null;
  function northMarketEnter(){if(northMerchantView&&northMerchantView.dirty){toast('请先保存店铺修改，再进入云端功能');return false;}northMarketSessionActive=true;northMerchantView=null;northProductEdit=null;northMyView=null;northCouponView=null;northCouponPurchase=null;northOrderView=null;northCheckoutDraft=null;northPinEntry=null;northView=null;northPersonalView=null;if(cur().p!=='food'){northMarketOrigin=Object.assign({},cur());go('food');}return true;}
  var northMarketOrderSeller=false;
  window.northMarketOrders=async function(seller,after,force){if(northMarketBusy||!northMarketEnter())return;var account=actId(),epoch=++northMarketEpoch,key='orders:'+!!seller+':'+(after||''),cached=northMarketPageGet(key),view={page:'orders',account:account,seller:!!seller,busy:!cached,rows:cached?cached.rows:[],pendingSplits:cached?cached.pendingSplits:[],more:cached&&cached.more};northMarketOrderSeller=!!seller;northMarketView=view;closeModal();render();if(!force&&northMarketPageGet(key,15000))return;var changed=!cached;try{await northMarketEnsure();var results=await Promise.all([northMarketRpc('orders',{p_seller:!!seller,p_after:after||null},true),seller||after?Promise.resolve({splits:[]}):northMarketRpc('split_get',{p_id:null},true)]);if(epoch!==northMarketEpoch||account!==actId()||northMarketView!==view)return;var data={pendingSplits:(results[1].splits||[]).filter(function(g){return g.state==='pending';}),rows:(results[0].orders||[]).slice(0,20),more:(results[0].orders||[]).length>20};changed=!cached||JSON.stringify(cached)!==JSON.stringify(data);Object.assign(view,data);northMarketPagePut(key,data);}catch(error){if(epoch===northMarketEpoch&&northMarketView===view){view.error=error.message;northMarketPageReset();changed=true;}}finally{if(epoch===northMarketEpoch&&northMarketView===view){view.busy=false;if(changed)northMarketPagePaint();}}};
  function northMarketStatus(status){return {delivered:'已送达，待确认收货',paid:'等待店主接单',accepted:'店主制作中',ready:'已发货，待确认收货',completed:'已完成',cancelled:'已取消／退款'}[status]||status;}
  function northMarketPendingSplitsHTML(v){return(v.pendingSplits||[]).map(function(g){var mine=g.is_host?g.host_paid:g.guest_paid,other=g.is_host?g.guest_paid:g.host_paid;return '<article class="north-merchant-card"><h3>'+esc(g.quote.shopName)+'</h3><p>'+esc(g.quote.items.map(function(p){return p.name;}).join('、'))+'</p><b>'+(other&&!mine?'好友已支付，等待你支付':mine?'你已支付，等待好友支付':'待支付 · 双方付齐后提交订单')+'</b><p>你的份额 ¥'+money((g.is_host?g.host_share:g.guest_share)/100)+'</p><button class="btn p" onclick="northMarketSplits(\''+g.id+'\')">查看拼单与付款</button></article>';}).join('');}
  function northMarketOrdersHTML(v){return '<header class="north-orders-header"><button onclick="northMarketClose()" aria-label="返回">'+mtGlyph('chevronLeft',23,'currentColor')+'</button><h2>'+ (v.seller?'顾客订单':'我的真人订单')+'</h2><button onclick="northMarketOrders('+!!v.seller+',null,true)">刷新</button></header><div class="north-orders-filters"><button onclick="northMarketOrders(false)" class="'+(!v.seller?'on':'')+'">我的订单</button><button onclick="northMarketOrders(true)" class="'+(v.seller?'on':'')+'">顾客订单</button><button onclick="northMarketSplits()">真人拼单</button><button onclick="northOrders()">本机模拟订单</button></div><div class="north-personal-scroll">'+(v.busy?'<div class="commerce-empty">正在读取订单…</div>':v.error?'<div class="commerce-empty">'+esc(v.error)+'</div>':v.rows.length?northMarketPendingSplitsHTML(v)+v.rows.map(function(o){return '<article class="north-history-card"><button class="north-history-head" onclick="northMarketOrder(\''+o.id+'\')">'+northMarketImage(o.shop_cover,o.shop_name)+'<b>'+esc(o.shop_name)+'</b><span>'+(o.auto_delivery_at&&o.status==='paid'?'准备中':northMarketStatus(o.status))+'</span></button><div class="north-check-product"><span class="north-sale-thumb">'+northMarketImage(o.items[0].image,o.items[0].name)+'</span><div><b>'+esc(o.items.map(function(p){return p.name;}).join('、'))+'</b><small>'+esc(fmtDT(o.created_at))+'</small></div><strong>¥'+money(o.total/100)+'</strong></div><div class="north-chips"><button onclick="northMarketOrder(\''+o.id+'\')">查看详情</button>'+(!v.seller&&o.is_buyer!==false&&o.status==='completed'?'<button onclick="northMarketReviewOpen(\''+o.id+'\')">评价／修改评价</button>':'')+'</div></article>';}).join(''):(v.pendingSplits||[]).length?northMarketPendingSplitsHTML(v):'<div class="commerce-empty">暂时没有真人店铺订单。</div>')+(v.more?'<button class="btn g" onclick="northMarketOrders('+v.seller+',\''+v.rows[v.rows.length-1].id+'\')">下一批订单</button>':'')+'</div>';}
  window.northMarketOrder=async function(id,force){if(northMarketBusy||!northMarketEnter())return;var account=actId(),epoch=++northMarketEpoch,key='order:'+id,cached=northMarketPageGet(key),view={page:'order',account:account,id:id,busy:!cached,data:cached};var same=northMarketView&&northMarketView.page==='order'&&northMarketView.id===id;northMarketView=view;closeModal();if(!same||!cached)render();if(!force&&northMarketPageGet(key,15000))return;var changed=!cached;try{await northMarketEnsure();var data=await northMarketRpc('order',{p_id:id},true);if(epoch!==northMarketEpoch||account!==actId()||northMarketView!==view)return;changed=!cached||JSON.stringify(cached)!==JSON.stringify(data);view.data=data;northMarketPagePut(key,data);}catch(error){if(epoch===northMarketEpoch&&northMarketView===view){view.error=error.message;northMarketPageReset();changed=true;}}finally{if(epoch===northMarketEpoch&&northMarketView===view){view.busy=false;if(changed)northMarketPagePaint();}}};
  function northMarketOrderHTML(v){if(v.busy||v.error||!v.data)return northMarketHeader('真人订单详情')+'<div class="commerce-empty">'+esc(v.error||'正在读取订单…')+'</div>';var o=v.data.order,buyer=v.data.isBuyer,manual=!o.auto_delivery_at;return '<div class="north-cloud-order-detail"><header class="north-order-top"><button onclick="northMarketOrders('+!!v.data.isSeller+')" aria-label="返回订单列表">'+mtGlyph('chevronLeft',23,'currentColor')+'</button><b>'+esc(o.shop_name)+'</b><span>真人店铺</span></header><div class="north-order-scroll"><section class="north-status-card">'+northMarketProgress(o)+'<div class="north-order-actions">'+(manual&&v.data.isSeller&&o.status==='paid'?'<button onclick="northMarketStatusChange(\''+o.id+'\',\'accepted\')">接单</button>':'')+(manual&&v.data.isSeller&&o.status==='accepted'?'<button onclick="northMarketStatusChange(\''+o.id+'\',\'ready\')">确认已发货</button>':'')+(manual&&v.data.isSeller&&o.status==='ready'?'<button onclick="northMarketStatusChange(\''+o.id+'\',\'delivered\')">确认已送达</button>':'')+(manual&&buyer&&['ready','delivered'].includes(o.status)?'<button onclick="northMarketStatusChange(\''+o.id+'\',\'completed\')">确认收货</button>':'')+((buyer&&o.status==='paid'||v.data.isSeller&&['paid','accepted','ready','delivered'].includes(o.status))?'<button onclick="northMarketStatusChange(\''+o.id+'\',\'cancelled\')">取消并退款</button>':'')+(buyer&&o.status==='completed'?'<button onclick="northMarketReviewOpen(\''+o.id+'\')">评价／修改评价</button>':'')+'<button onclick="northMarketOrder('+northMarketArgument(o.id)+')">刷新状态</button><button onclick="northMarketOrders('+!!v.data.isSeller+')">返回订单列表</button></div></section><section class="north-detail-card"><h3>订单信息</h3><p>配送地址：'+esc(o.address.address)+'</p><p>收货人：'+esc(o.address.name)+' '+esc(o.address.phone||'')+'</p><p>餐具：'+(o.utensils?'需要':'不需要')+'</p><p>备注：'+esc(o.note||'未填写')+'</p><p>付款方式：'+(o.payer_role?'情侣云银行卡':'本人美团云端钱包')+'</p><small>订单号 '+esc(o.id)+'<br>'+esc(fmtDT(o.created_at))+'</small></section><section class="north-detail-card"><h3>商品费用</h3>'+o.items.map(function(p){return '<div class="north-check-product"><span class="north-sale-thumb">'+northMarketImage(p.image,p.name)+'</span><div><b>'+northSignatureBadge(p.signature)+esc(p.name)+'</b><small>'+esc(p.labels.join('／'))+' · ×'+p.quantity+'</small></div><strong>¥'+money(p.total/100)+'</strong></div>';}).join('')+'<div class="north-check-line"><span>商品合计</span><b>¥'+money(o.subtotal/100)+'</b></div><div class="north-check-line"><span>配送费</span><b>¥'+money(o.delivery/100)+'</b></div>'+(o.discount?'<div class="north-check-line"><span>神券优惠</span><b>−¥'+money(o.discount/100)+'</b></div>':'')+'<div class="north-check-line"><span>实付</span><b>¥'+money(o.total/100)+'</b></div></section></div>';}
  window.northMarketStatusChange=async function(id,status){if(northMarketBusy)return;northMarketBusy=true;try{await northMarketRpc('order_status',{p_id:id,p_status:status},true);northMarketWalletCache=null;toast(status==='completed'?'已确认收货，店铺收入完成结算':status==='cancelled'?'订单已取消，实际支付虚拟币已退款':'订单状态已更新');}catch(error){toast(error.message);}finally{northMarketBusy=false;}return await northMarketOrder(id);};
  window.northMarketReviews=async function(id,after){if(!northMarketEnter())return;if(northMarketBusy)return;var account=actId(),epoch=++northMarketEpoch;northMarketView={page:'reviews',account:account,id:id,busy:true,rows:[]};northMarketBusy=true;render();try{var data=await northMarketRpc('reviews',{p_shop:id,p_after:after||null});if(epoch!==northMarketEpoch)return;northMarketView.rows=(data.reviews||[]).slice(0,8);northMarketView.more=(data.reviews||[]).length>8;northMarketView.rating=data.rating;northMarketView.count=data.count;}catch(error){if(epoch===northMarketEpoch&&northMarketView)northMarketView.error=error.message;}finally{if(epoch===northMarketEpoch&&northMarketView){northMarketBusy=false;northMarketView.busy=false;render();}}};
  function northMarketReviewsHTML(v){return northMarketHeader('店铺真实评价')+'<div class="north-personal-scroll">'+(v.busy?'<div class="commerce-empty">正在读取评价…</div>':v.error?'<div class="commerce-empty">'+esc(v.error)+'</div>':'<section class="north-merchant-card"><h3>'+(v.rating==null?'暂无评分':v.rating+'分')+' · '+v.count+'条有效订单评价</h3><small>一张已完成订单一条评价，修改不重复计数。</small></section>'+v.rows.map(function(r){return '<article class="north-review north-personal-review"><div class="north-review-head"><img src="assets/meituan-kangaroo.png" alt="评价头像"><div><b>'+esc(r.name)+'</b><small>'+('★'.repeat(r.rating))+' 商品'+r.rating+'星'+(r.packaging?' · 包装'+r.packaging+'星':'')+'</small></div><time>'+esc(fmtDT(r.updated_at))+'</time></div>'+(r.text?'<p>'+esc(r.text)+'</p>':'')+'<div class="north-published-images">'+r.images.map(function(url){return '<span class="north-market-review-photo">'+northMarketImage(url,'评价照片')+'</span>';}).join('')+'</div><small>'+esc((r.products||[]).join('、'))+'</small>'+northMarketReplyHTML(r)+'</article>';}).join('')+(!v.rows.length?'<div class="commerce-empty">还没有购买者评价。</div>':'')+(v.more?'<button class="btn g" onclick="northMarketReviews(\''+v.id+'\',\''+v.rows[v.rows.length-1].order_id+'\')">下一批评价</button>':'')+'<button class="btn g" onclick="northMarketOpen(\''+v.id+'\')">返回店铺</button>')+'</div>';}
  var northMarketReviewDraft=null;
  var northMarketInboxCache=null,northMarketSplitRows=[],northMarketSplitDraft=null;
  function northMarketSplitInvites(){var d=northData();d.marketSplitInvites=d.marketSplitInvites||[];return d.marketSplitInvites;}
  async function northMarketResumeSplit(entry){if(northMarketBusy)return;northMarketBusy=true;try{if(entry.phone!==phoneFriendState().id){toast('账号身份已变化，请到真人拼单核对原邀请');return;}var data=await northMarketRpc('split_get',{p_id:entry.id||null,p_client:entry.client},true),g=(data.splits||[]).find(function(g){return g.id===entry.id||g.client_id===entry.client;});if(g){entry.id=g.id;entry.status=g.state;await saveNowAsync();if(g.state==='paid'){var rows=entry.snapshot.rows;await northCommit(function(){var before=S.food.cart.slice();S.food.cart=S.food.cart.filter(function(p){return !rows.includes(p._northRow)||p._northAccount!==actId();});return function(){S.food.cart=before;};});}if(['cancelled','expired'].includes(g.state)){toast('原拼单已关闭并退款，可以重新选择结算');return;}northMarketBusy=false;return await northMarketSplits(g.id);}openModal('<div class="north-flow"><h3>核对原拼单邀请</h3><p>后台暂未找到这条邀请。重试使用原请求编号，不会重复创建。</p><button class="btn p" onclick="northMarketSplitRetry(\''+entry.client+'\')">重试原邀请</button><button class="btn g" onclick="closeModal()">稍后核对</button></div>');}catch(error){toast('请稍后核对原拼单：'+error.message);}finally{northMarketBusy=false;}}
  window.northMarketSplitRetry=function(client){var e=northMarketSplitInvites().find(function(e){return e.client===client&&e.account===actId();});if(!e||e.phone!==phoneFriendState().id)return;northMarketPayDraft=Object.assign(JSON.parse(JSON.stringify(e.snapshot)),{state:S,lockedRequest:false});northMarketSplitCreate(e.friend);};
  var northMarketMyCache=null,northMarketMetaLoading=false;
  var northBusinessCache=null,northBusinessDraft=null;
  window.northMarketBusiness=async function(){if(northMarketBusy||!northMarketEnter())return;var account=actId(),epoch=++northMarketEpoch;northMarketBusy=true;northMarketView={page:'business',account:account,busy:true,data:null};render();try{await northMarketEnsure();var data=await northMarketRpc('business',{},true);if(account!==actId()||epoch!==northMarketEpoch)return;northBusinessCache={account:account,state:S,data:data,at:Date.now()};northMarketView.data=data;}catch(error){if(epoch===northMarketEpoch)northMarketView.error=error.message;}finally{if(epoch===northMarketEpoch){northMarketBusy=false;northMarketView.busy=false;render();}}};
  function northMarketBusinessHTML(v){var d=v.data;return northMarketHeader('共同经营 · 我的店铺')+'<div class="north-personal-scroll">'+(v.busy?'<div class="commerce-empty">正在核对经营账本…</div>':v.error?'<div class="commerce-empty">'+esc(v.error)+'</div>':((northData().businessPending&&northData().businessPending.account===actId())?'<section class="north-merchant-card"><button class="btn p" onclick="northBusinessRetry()">核对上一笔补货或开店请求</button></section>':'')+'<section class="north-merchant-card"><h3>经营账本</h3><div class="north-check-line"><span>可用店铺收入</span><b>¥'+money(d.income/100)+'</b></div><div class="north-check-line"><span>已实现净利润</span><b>¥'+money(d.profit/100)+'</b></div><div class="north-check-line"><span>未售库存资产</span><b>¥'+money(d.inventoryValue/100)+'</b></div><small>补货先占用资金；已完成订单减去实际进货成本及创业费用后计算利润。库存资产不是可直接消费的余额。</small><button class="btn p" onclick="northMarketWallet()">云端交易钱包</button></section><section class="north-merchant-card"><h3>我的店铺 · '+d.shopCount+'/3家</h3>'+d.shops.map(function(shop){return '<div class="north-business-shop"><b>'+esc(shop.name)+'</b><small>'+ (shop.published?'公开营业':'暂未公开')+' · 收入 ¥'+money(shop.revenue/100)+' · 已售成本 ¥'+money(shop.cost/100)+'</small><div class="north-chips"><button onclick="northMarketManageMine(false,\''+shop.id+'\')">管理店铺</button><button onclick="northMarketOpen(\''+shop.id+'\')">查看店铺</button></div></div>';}).join('')+(d.shopCount<3?'<button class="btn p" onclick="northBusinessCreateOpen()">'+(d.shopCount?'再开一家 · 创业费 ¥'+money(d.nextStartupFee/100):'开第一家 · 无创业费')+'</button>':'<small>已达到三家上限；已有店铺可修改经营方向，重新营业不重复收创业费。</small>')+'</section><section class="north-merchant-card"><h3>补货与库存</h3><button class="btn p" onclick="northBusinessBatchOpen()">所有商品一键补货</button><small>单次进货1至1000份，成本按商品基础售价40%计算。未售库存可按原进货成本退回，原料不能凭空增加。缺货提醒每次补货周期仅一次。</small>'+d.stock.map(function(row){return '<article class="north-business-stock"><div><b>'+esc(row.name)+'</b><small>'+esc(row.shop_name)+' · 可售 '+row.quantity+' '+esc(row.unit)+(row.quantity?'':' · 已卖完')+'</small><small>库存成本 ¥'+money(row.cost_value/100)+'</small></div><div class="north-chips">'+(row.sale_price!=null?'<button onclick="northBusinessStockOpen(\''+row.shop_id+'\',\''+row.product_id+'\',false)">补货</button>':'')+(row.quantity?'<button onclick="northBusinessStockOpen(\''+row.shop_id+'\',\''+row.product_id+'\',true)">退未售库存</button>':'')+'</div></article>';}).join('')+(!d.stock.length?'<p>先在店铺管理里保存商品，再回来补货。</p>':'')+'</section>')+'</div>';}

  function northBusinessBatchQuote(rows,quantity){if(!Number.isInteger(quantity)||quantity<1||quantity>1000||!Array.isArray(rows)||!rows.length||rows.length>150)return null;var lines=[],total=0,keys=new Set();for(var row of rows){var key=row.shop_id+':'+row.product_id;if(keys.has(key)||!Number.isInteger(row.sale_price)||row.sale_price<3||row.sale_price>999999||!Number.isInteger(row.quantity)||row.quantity<0||row.quantity+quantity>9999)return null;keys.add(key);var fee=Math.max(1,Math.floor(row.sale_price*.4))*quantity;total+=fee;lines.push({shopId:row.shop_id,productId:row.product_id,quantity:quantity,expected:fee});}return Number.isSafeInteger(total)&&total<=2147483647?{lines:lines,total:total}:null;}
  window.northBusinessBatchOpen=function(){if(northMarketBusy)return;if(northData().businessPending&&northData().businessPending.account===actId())return northBusinessRetry();var c=northBusinessCache,data=c&&c.account===actId()&&c.data,rows=data&&(data.stock||[]).filter(function(r){return r.sale_price!=null&&r.sale_price>=3;});if(!rows||!rows.length){toast('先保存可补货商品');return;}northBusinessDraft={kind:'business-batch',account:actId(),state:S,client:crypto.randomUUID(),rows:rows,source:'wallet',quantity:1,fee:0};openModal('<div class="north-flow north-merchant-form"><h3>所有商品 · 一键补货</h3><p>共'+rows.length+'件商品；以下数量是每件商品增加的库存，整批一次确认。未在售商品请在店铺管理中核对。</p><label>每件补货数量<input id="north_business_batch_quantity" type="number" min="1" max="1000" step="1" value="1" oninput="northBusinessBatchPreview()"></label><label>付款来源<select id="north_business_source"><option value="wallet">本人云端余额 · ¥'+money(data.balance/100)+'</option><option value="income">未提现店铺收入 · ¥'+money(data.income/100)+'</option></select></label><div id="north_business_batch_lines"></div><b id="north_business_batch_cost"></b><p>整批扣款和入库；余额不足、价格变化或库存超限时，全部不扣款。补货成本仍为基础售价40%。</p><button class="btn p" id="north_business_batch_confirm" onclick="northBusinessBatchConfirm()">确认整批补货</button><button class="btn g" onclick="closeModal()">取消</button></div>');northBusinessBatchPreview();};
  window.northBusinessBatchPreview=function(){var d=northBusinessDraft,input=document.getElementById('north_business_batch_quantity');if(!d||d.kind!=='business-batch'||d.account!==actId()||!input)return;var q=northBusinessBatchQuote(d.rows,+input.value);d.quoteBatch=q;var cost=document.getElementById('north_business_batch_cost'),button=document.getElementById('north_business_batch_confirm'),list=document.getElementById('north_business_batch_lines');if(button)button.disabled=!q;if(cost)cost.textContent=q?'总成本 ¥'+money(q.total/100):'数量无效或有商品超过库存上限';if(list)list.innerHTML=q?d.rows.map(function(r,i){return '<div class="north-check-line"><span>'+esc(r.shop_name)+' · '+esc(r.name)+'<small>现有 '+r.quantity+' → '+(r.quantity+ +input.value)+' '+esc(r.unit)+'</small></span><b>¥'+money(q.lines[i].expected/100)+'</b></div>';}).join(''):'';};
  window.northBusinessBatchConfirm=function(){var d=northBusinessDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy)return;northBusinessBatchPreview();if(!d.quoteBatch)return;var source=document.getElementById('north_business_source').value;if(!['wallet','income'].includes(source))return;d.source=source;d.lines=d.quoteBatch.lines;d.fee=d.quoteBatch.total;northMarketPayDraft=Object.assign({},d,{quote:{shopName:'所有商品 · 整批补货',total:d.fee},roleId:''});northMarketPinOpen();};
  var northQuickCategories=['美食','甜点饮品','超市便利','蔬菜水果','买药用品','夜宵','快食简餐'];
  function northMerchantQuickTagsHTML(){var d=northMerchantView.draft,selected=String(d.category||'').split(/[、，,]/).map(function(t){return t.trim();});return '<div class="north-chips north-quick-category-tags">'+northQuickCategories.map(function(tag,i){return '<button type="button" class="'+(selected.includes(tag)?'on':'')+'" aria-pressed="'+selected.includes(tag)+'" onclick="northMerchantQuickTag('+i+')">'+tag+'</button>';}).join('')+'</div><small>可多选，发布后首页快捷分类与关键词都能找到店铺。再次点击可取消。</small>';}
  window.northMerchantQuickTag=function(index){if(!northMerchantActive()||northSaving||!northQuickCategories[index])return;var d=northMerchantView.draft,tag=northQuickCategories[index],tags=String(d.category||'').split(/[、，,]/).map(function(t){return t.trim();}).filter(function(t){return t&&t!=='其他';});if(tags.includes(tag))tags=tags.filter(function(t){return t!==tag;});else tags.push(tag);var value=tags.join('、')||'其他';if(value.length>30){toast('分类标签合计最多30字，请先取消其他分类');return;}d.category=value;northMerchantView.dirty=true;render();};

  window.northBusinessCreateOpen=function(){if(northData().businessPending&&northData().businessPending.account===actId())return northBusinessRetry();var cache=northBusinessCache,d=cache&&cache.account===actId()&&cache.data;if(!d||d.shopCount>=3)return;if(d.nextStartupFee&&d.profit<d.nextStartupFee){toast('已实现净利润还不足以承担下一家店的创业费');return;}if(d.nextStartupFee&&d.income<d.nextStartupFee){toast('创业费需要保留足够的未提现店铺收入');return;}northBusinessDraft={kind:'business-create',account:actId(),state:S,client:crypto.randomUUID(),fee:d.nextStartupFee,shopName:'',category:''};openModal('<div class="north-flow north-merchant-form"><h3>开第'+(d.shopCount+1)+'家店</h3><p>本次创业费 ¥'+money(d.nextStartupFee/100)+'，'+(d.nextStartupFee?'从未提现店铺收入支付。':'第一家免费。')+'保存、设计菜单不收费；出售商品前需要补货。</p><label>店铺名字<input id="north_business_name" maxlength="40"></label><label>主营分类<input id="north_business_category" maxlength="40" placeholder="奶茶、蛋糕、家常菜…"></label><button class="btn p" onclick="northBusinessConfirm()">确认创建</button><button class="btn g" onclick="closeModal()">取消</button></div>');};
  window.northBusinessStockOpen=function(shop,product,returning){if(northData().businessPending&&northData().businessPending.account===actId())return northBusinessRetry();var c=northBusinessCache,row=c&&c.account===actId()&&c.data.stock.find(function(r){return r.shop_id===shop&&r.product_id===product;});if(!row||returning&&!row.quantity||!returning&&(row.sale_price==null||row.sale_price<3))return;northBusinessDraft={kind:'business-stock',account:actId(),state:S,client:crypto.randomUUID(),shop:shop,product:product,returning:!!returning,row:row,source:'wallet',quantity:1,fee:0};openModal('<div class="north-flow north-merchant-form"><h3>'+esc(row.name)+' · '+(returning?'退未售库存':'补货')+'</h3><p>当前可售 '+row.quantity+' '+esc(row.unit)+'</p>'+(!returning?'<p>本次进货单价 ¥'+money(Math.max(1,Math.floor(row.sale_price*.4))/100)+' · 基础售价 ¥'+money(row.sale_price/100)+'</p><label>付款来源<select id="north_business_source"><option value="wallet">本人云端余额 · ¥'+money(c.data.balance/100)+'</option><option value="income">未提现店铺收入 · ¥'+money(c.data.income/100)+'</option></select></label>':'<p>退回实际未售批次的原成本和原付款来源，不形成营业收入。</p>')+'<label>数量<input id="north_business_quantity" type="number" min="1" max="'+Math.min(1000,returning?row.quantity:9999-row.quantity)+'" step="1" value="1" oninput="northBusinessCostPreview()"></label><b id="north_business_cost"></b><button class="btn p" onclick="northBusinessConfirm()">'+(returning?'确认退库':'确认补货')+'</button><button class="btn g" onclick="closeModal()">取消</button></div>');northBusinessCostPreview();};
  window.northBusinessCostPreview=function(){var d=northBusinessDraft,input=document.getElementById('north_business_quantity');if(!d||d.kind!=='business-stock'||!input)return;var quantity=+input.value,fee=0;if(!Number.isInteger(quantity)||quantity<1||quantity>1000||d.returning&&quantity>d.row.quantity){document.getElementById('north_business_cost').textContent='请选择有效数量';return;}if(d.returning){var left=quantity;for(var lot of d.row.lots){var count=Math.min(left,lot.quantity);fee+=count*lot.unitCost;left-=count;if(!left)break;}if(left)return;}else fee=quantity*Math.max(1,Math.floor(d.row.sale_price*.4));d.quantity=quantity;d.fee=fee;document.getElementById('north_business_cost').textContent=(d.returning?'原路退回':'本次支付')+' ¥'+money(fee/100);};
  window.northBusinessConfirm=function(){var d=northBusinessDraft;if(!d||d.account!==actId()||d.state!==S||northMarketBusy)return;if(d.kind==='business-create'){d.shopName=document.getElementById('north_business_name').value.trim();d.category=document.getElementById('north_business_category').value.trim();if(!d.shopName||!d.category){toast('请填写店名和分类');return;}}else{northBusinessCostPreview();var input=document.getElementById('north_business_quantity');if(+input.value!==d.quantity||!d.fee){toast('请核对数量和金额');return;}var source=document.getElementById('north_business_source');d.source=source?source.value:'wallet';}northMarketPayDraft=Object.assign({},d,{quote:{shopName:d.kind==='business-create'?'店铺创业费':d.returning?'退未售库存':'库存补货',total:d.fee},roleId:''});if(d.kind==='business-create'&&!d.fee)return northBusinessSubmit('');northMarketPinOpen();};
