  function northVisibleCartRows(){return(S.food.cart||[]).filter(function(p){return deliveryRealEnabled()?(!p._northAccount||p._northAccount===actId())&&!!p.offerId:p._northAccount===actId()&&!p.offerId&&!!(p._northMarket||p._northGeneric||p._northSku||p._northMerchant);});}
  function mtPaintCart(){var button=document.querySelector('.mt-home .mt-cart-float');if(!button)return;var count=northVisibleCartRows().reduce(function(n,p){return n+(Number.isInteger(+p.quantity)&&+p.quantity>0?+p.quantity:1);},0),badge=button.querySelector('.badge');if(!count){if(badge)badge.remove();return;}if(!badge){badge=document.createElement('span');badge.className='badge';button.appendChild(badge);}badge.textContent=String(count);}
  function mtLocalCart(core,real){return function(i){var mode=typeof deliveryRealEnabled==='function'&&deliveryRealEnabled();if(typeof document==='undefined'||!document.querySelector||!document.querySelector('.mt-home')||mode!==real)return core&&core.apply(this,arguments);var p=(S.food.results||[])[i];if(!p)return;if(real&&(S.food.cart||[]).some(function(x){return x.offerId===p.offerId;})){toast('已经在外卖单里');return;}S.food.cart=S.food.cart||[];S.food.cart.push(p);save();mtPaintCart();toast('已加入外卖单');};}
