  window.northEdit=function(id){if(!northAllowed()||northSaving)return;var row=(S.food.cart||[]).find(function(p){return northOwned(p)&&p._northRow===id;});if(!row)return;var index=northMenu.findIndex(function(p){return p.id===row._northSku;});if(index<0)return;northSpecs(index);northPending.editRow=row;northSpecChoice('north_size',row._northSize||(/大杯/.test(row.name)?'large':'standard'));northSpecChoice('north_sugar',row._northSugar||(/半糖/.test(row.name)?'半糖':/不另加糖/.test(row.name)?'不另加糖':/少糖/.test(row.name)?'少糖':'正常糖'));northSpecChoice('north_ice',row._northIce||(/温热/.test(row.name)?'温热':/少冰/.test(row.name)?'少冰':/去冰/.test(row.name)?'去冰':'正常冰'));document.getElementById('north_qty').value=row.quantity||1;document.querySelectorAll('.north-addon-choice input').forEach(function(el){el.checked=(row._northExtras||[]).includes(el.dataset.extra);});northSpecUpdate();};
