  var northReviewEditor=null;
  window.northWriteReview=function(id){if(deliveryRealEnabled())return;var o=northFind(id);if(!o||o.status!=='completed')return;var r=o.review||{rating:null,text:''};northReviewEditor={id:id,account:actId(),returnToMy:northPersonalActive()&&northPersonalView.page==='reviews'};openModal('<div class="north-flow"><h3>评价这笔订单</h3><p>'+esc(o.items[0].name)+'</p><label>店铺评分<select id="north_review_rating"><option value="" '+(r.rating==null?'selected':'')+'>请选择星级</option>'+[5,4,3,2,1].map(function(n){return '<option '+(r.rating===n?'selected':'')+' value="'+n+'">'+n+'星</option>';}).join('')+'</select></label><label>我的评价<textarea id="north_review_text" maxlength="300" placeholder="文字可不填，也可以说说口味和包装">'+esc(r.text)+'</textarea></label><small>已完成订单一单一评，可以只打星；修改与追评不增加条数。当前为本机评价。</small><button class="btn p" onclick="northSaveReview(\''+id+'\')">保存评价</button><button class="btn g" onclick="'+(northReviewEditor.returnToMy?'northMyReviews()':'northOrder(\''+id+'\')')+'">'+(northReviewEditor.returnToMy?'返回我的评价':'返回订单')+'</button></div>');};
  window.northSaveReview=async function(id){if(deliveryRealEnabled()||northSaving)return;var o=northFind(id),field=document.getElementById('north_review_text'),stars=document.getElementById('north_review_rating');if(!o||o.status!=='completed'||!field||!stars)return;var text=field.value.trim(),rating=+stars.value,prior=o.review,account=actId(),editor=northReviewEditor;if(editor&&(editor.id!==id||editor.account!==account||editor.uploading))return;if(editor&&editor.previousReference!==(prior||null)){toast('评价已经更新，请重新打开');return;}var limit=editor?editor.textLimit:Math.max(200,prior&&prior.text&&prior.text.length||0);if(text.length>limit||![1,2,3,4,5].includes(rating)){toast('请选择1至5星，文字不得超过长度限制');return;}var anonymous=editor?editor.anonymous:!!(prior&&prior.anonymous),ok=await northCommit(function(){o.review={rating:rating,text:text,packagingRating:editor?editor.packagingRating:prior&&prior.packagingRating||null,anonymous:anonymous,images:editor?editor.images.slice():prior&&prior.images||[],courier:editor?JSON.parse(JSON.stringify(editor.courier)):prior&&prior.courier||null,source:'local',createdAt:prior?prior.createdAt:Date.now(),updatedAt:Date.now(),followups:prior&&prior.followups||[],name:anonymous?'匿名顾客':S.me.name||'我'};return function(){if(prior)o.review=prior;else delete o.review;};});if(ok&&actId()===account){northReviewStopVoice();northReviewEditor=null;if(editor)await northReviewCleanup(editor);if(editor&&editor.returnToMy)northMyReviews();else northOrder(id);toast('评价已保存，同一订单只保留一条');}};
