  window.northCouponEmpty=function(){toast('暂无可用优惠券');};
  window.northPay=function(){var draft=northCheckoutDraft;if(northSaving||!draft||draft.account!==actId()||deliveryRealEnabled())return;if(draft.pendingFunding){toast('请先选择付款角色或亲属卡');northPaymentMethods(draft.pendingFunding);return;}var receiver=document.getElementById('north_receiver'),address=document.getElementById('north_address'),note=document.getElementById('north_note');if(!receiver||!address||!receiver.value.trim()||!address.value.trim()){toast('请填写收货称呼和位置');return;}draft.shipping={phone:draft.shipping&&draft.shipping.phone||northData().addresses&&northData().addresses[actId()]&&northData().addresses[actId()].phone||'',receiver:receiver.value.trim().slice(0,30),address:address.value.trim().slice(0,80),note:note?note.value.trim().slice(0,120):''};draft.utensils=null;northPinEntry=null;openModal('<div class="north-flow north-utensils"><button class="north-flow-close" onclick="northClosePayment()" aria-label="关闭">×</button><p>'+esc(draft.shipping.address)+'<br><small>'+esc(draft.shipping.receiver)+'</small></p><h3>当前地址下单，是否需要餐具？</h3><div class="north-utensil-options"><button onclick="northUtensils(\'yes\')">需要餐具</button><button onclick="northUtensils(\'no\')">无需餐具<small>轻装出发</small></button></div><button class="btn p" id="north_utensil_save" onclick="northUtensilSave()" disabled>保存并继续</button></div>');};
