  function northPasswordPage(){var draft=northPaymentDraft();if(!draft||!northPinEntry)return;draft.expectedTotal=northPaymentAmount(draft);openModal('<div class="north-flow north-password"><button class="north-flow-close" onclick="northClosePayment()" aria-label="关闭支付">×</button><p>'+esc(draft.kind==='coupon-pack'?'神券包':draft.kind==='income-withdraw'?'店铺收入提现到微信':draft.shop||northShopName)+'</p><h2>¥'+(northPaymentAmount(draft)/100).toFixed(2)+'</h2><div class="north-check-line"><span>'+(draft.kind==='income-withdraw'?'到账位置':'付款方式')+'</span><b>'+esc(draft.kind==='income-withdraw'?'微信零钱':northFundingLabel(draft.funding))+'</b></div><div class="north-password-dots" aria-label="五位支付密码">'+[0,1,2,3,4].map(function(){return '<span></span>';}).join('')+'</div><p class="north-password-error" aria-live="polite">请输入五位支付密码</p><div class="north-keypad">'+['1','2','3','4','5','6','7','8','9','cancel','0','delete'].map(function(key){return '<button data-digit="'+key+'" onclick="northPinKey(\''+key+'\')" aria-label="'+(key==='delete'?'删除一位':key==='cancel'?'取消支付':key)+'">'+(key==='delete'?'⌫':key==='cancel'?'取消':key)+'</button>';}).join('')+'</div></div>');}
