  async function northPinHash(value,salt){if(!crypto||!crypto.subtle)throw Error('当前入口无法核验密码');var bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+'|'+value));return Array.from(new Uint8Array(bytes),function(b){return b.toString(16).padStart(2,'0');}).join('');}
