  function northFundingLabel(f){f=f||{mode:'wallet'};if(f.mode==='wallet')return '微信零钱';if(f.mode==='bank'){var b=(S.me.wxFeatures&&S.me.wxFeatures.banks||[]).find(function(b){return b.id===f.id;});return b?(b.name+' · '+b.last4):'微信模拟银行卡';}var c=typeof getC==='function'&&getC(f.id),name=c&&(c.remark||c.name)||'角色';return f.mode==='family'?'亲属卡 · '+name:'角色代付 · '+name;}
