  window.northRequestRolePay=async function(){var d=northCheckoutDraft;if(northSaving||!d||d.account!==actId()||!d.utensils||!d.funding||d.funding.mode!=='role')return;var c=getC(d.funding.id);if(!c||c.deleted||c.blocked||c.isPhoneFriend||northFundingAvailable(d.funding)<northPaymentAmount(d)){toast('这个角色的钱包未设置或不足，尚未发送请求');return;}if(msgs(c.id).some(function(m){return m.role==='user'&&m.type==='paycard'&&!m._paid&&!m._rejected&&(!m.northRequestId||northPayRequests().some(function(r){return r.id===m.northRequestId&&r.account===actId()&&r.status==='pending'&&r.expiresAt>Date.now();}));})){toast('请先等这位角色处理上一笔代付');return;}var account=actId(),request={id:d.token,account:account,roleId:c.id,status:'pending',createdAt:Date.now(),expiresAt:Date.now()+30*60000,draft:JSON.parse(JSON.stringify(d))};request.draft.expectedTotal=northPaymentAmount(d);var message={id:uid(),time:Date.now(),role:'user',type:'paycard',kind:'food',shop:d.shop||northShopName,name:d.items.map(function(p){return p.name;}).join('、'),price:northPaymentAmount(d)/100,northRequestId:request.id};var list=msgs(c.id);var ok=await northCommit(function(){northPayRequests().push(request);list.push(message);return function(){var i=northPayRequests().indexOf(request);if(i>=0)northPayRequests().splice(i,1);var j=list.indexOf(message);if(j>=0)list.splice(j,1);};});if(ok&&account===actId()){northCheckoutDraft=null;northPinEntry=null;closeModal();northRoleRequestView(request.id);toast('已请求角色代付，尚未扣款');if(typeof replyTouch==='function')replyTouch(c.id);if(typeof wechatTailJournalWrite==='function')wechatTailJournalWrite(c.id,account);if(typeof roleBackgroundCancel==='function')roleBackgroundCancel(c.id,['one_minute_test','app_watch_test']);save();scheduleReply(c.id);}};
  window.northRoleRequestView=function(id){var r=northPayRequests().find(function(r){return r.id===id&&r.account===actId();});if(!r)return;openModal('<div class="north-flow north-merchant-form"><h3>'+({pending:'等待角色同意',paid:'角色已代付',rejected:'角色已拒绝',cancelled:'请求已取消',failed:'代付未完成',refunded:'代付订单已原路退款'}[r.status]||'代付请求')+'</h3><p>'+esc(r.draft.items.map(function(p){return p.name;}).join('、'))+'</p><b>¥'+money(r.draft.expectedTotal/100)+'</b><p>请求编号 '+esc(r.id)+'</p>'+(r.status==='pending'?'<button class="btn g" onclick="northCancelRoleRequest(\''+r.id+'\')">取消本次代付请求</button>':'')+((r.status==='paid'||r.status==='refunded')?'<button class="btn p" onclick="northOrder(\''+r.orderId+'\')">查看订单</button>':'')+'<button class="btn g" onclick="closeModal()">关闭</button></div>');};
  window.northCancelRoleRequest=async function(id){var r=northPayRequests().find(function(r){return r.id===id&&r.account===actId();});if(!r||r.status!=='pending'||northSaving)return;var account=actId(),message=msgs(r.roleId).find(function(m){return m.northRequestId===id;}),prior=message&&message._rejected,ok=await northCommit(function(){r.status='cancelled';if(message)message._rejected=true;return function(){r.status='pending';if(message){if(prior===undefined)delete message._rejected;else message._rejected=prior;}};});if(ok&&account===actId())northRoleRequestView(id);};
  var northRoleDecisionQueue=Promise.resolve();
  window.NorthCommercePayment={roleDecision:function(c,id,reject){var capturedAccount=actId();northRoleDecisionQueue=northRoleDecisionQueue.catch(function(){}).then(async function(){var r=northPayRequests().find(function(r){return r.id===id&&r.account===capturedAccount&&r.roleId===c.id;});if(!r||capturedAccount!==actId())return false;if(r.status==='paid'||r.status==='refunded')return true;if(r.status!=='pending')return false;var sourceMessage=msgs(c.id).find(function(m){return m.role==='user'&&m.type==='paycard'&&m.northRequestId===id;});if(!sourceMessage||sourceMessage.recalled||sourceMessage._rejected||c.deleted||c.blocked||c.isPhoneFriend){await northCommit(function(){r.status='cancelled';return function(){r.status='pending';};});return false;}if(reject||r.expiresAt<=Date.now()){var prior=r.status,ok=await northCommit(function(){r.status=reject?'rejected':'failed';return function(){r.status=prior;};});if(ok){var m=msgs(c.id).find(function(m){return m.northRequestId===id;});if(m)m._rejected=true;pushMsg(c.id,{role:'assistant',type:'payreject',price:r.draft.expectedTotal/100,name:r.draft.items.map(function(p){return p.name;}).join('、'),id:uid(),time:Date.now()});save();}return ok;}var wait=0;while(northSaving&&wait<5000&&actId()===capturedAccount){await new Promise(function(resolve){setTimeout(resolve,50);});wait+=50;}if(northSaving||actId()!==capturedAccount||deliveryRealEnabled()||r.status!=='pending'||c.deleted||c.blocked||!msgs(c.id).some(function(m){return m.role==='user'&&m.type==='paycard'&&m.northRequestId===id&&!m.recalled&&!m._rejected;}))return false;var previous=northCheckoutDraft,d=JSON.parse(JSON.stringify(r.draft));d.authorized=true;d.roleRequestId=id;if(d.fromCart){var rows=d.items.map(function(item){return(S.food.cart||[]).find(function(p){return p._northRow&&p._northRow===item._northRow&&p._northAccount===item._northAccount&&p.name===item.name&&p.price===item.price&&p.quantity===item.quantity&&JSON.stringify(p._northSelections||{})===JSON.stringify(item._northSelections||{})&&JSON.stringify(p._northExtras||[])===JSON.stringify(item._northExtras||[]);});});if(rows.some(function(p){return !p;}))return false;d.items=rows;}northCheckoutDraft=d;await northFinalizePay();if(northCheckoutDraft===d)northCheckoutDraft=previous;var paid=northFind(d.token);if(!paid)return false;var m=msgs(c.id).find(function(m){return m.northRequestId===id;});if(m)m._paid=true;pushMsg(c.id,{role:'assistant',type:'paid',price:paid.total/100,name:paid.items.map(function(p){return p.name;}).join('、'),id:uid(),time:Date.now()});save();return true;});return northRoleDecisionQueue;}};
  function northIncomeData(){var d=northData();d.incomeEntries=d.incomeEntries||[];d.withdrawals=d.withdrawals||[];return d;}
  function northIncomeEntries(){return northIncomeData().incomeEntries.filter(function(e){return e.owner===actId()&&e.source==='customer'&&e.buyer&&e.buyer!==actId()&&e.status==='settled'&&Number.isSafeInteger(e.amount)&&e.amount>0&&Number.isSafeInteger(e.withdrawn||0)&&(e.withdrawn||0)>=0&&(e.withdrawn||0)<=e.amount;});}
  function northIncomeAvailable(){return northIncomeEntries().reduce(function(n,e){return n+Math.max(0,e.amount-(e.withdrawn||0));},0);}
  window.northIncome=function(){northMerchantClearOtherViews();northMerchantView=null;northIncomeTransfer=null;northIncomeView={account:actId()};render();};
  function northIncomeRender(){var d=northIncomeData(),available=northIncomeAvailable(),earned=northIncomeEntries().reduce(function(n,e){return n+e.amount;},0),rows=d.withdrawals.filter(function(w){return w.account===actId();});return '<div class="mt-home north-income-page"><header class="north-merchant-header"><button onclick="northMy()">'+mtGlyph('chevronLeft',22,'currentColor')+'</button><b>我的收入</b></header><div class="north-merchant-scroll"><section class="north-my-card"><h3>店铺收入</h3><div class="north-my-assets"><div><small>累计已结算</small><b>¥'+money(earned/100)+'</b></div><div><small>可提现到微信</small><b>¥'+money(available/100)+'</b></div></div><button class="btn p" onclick="northIncomeWithdraw()" '+(!available?'disabled':'')+'>提现到微信</button><p class="north-merchant-note">顾客订单完成并结算后才产生收入。自己试买自己的店只用于测试，不计入可提现收入。当前本机阶段等待真人顾客订单接入。</p></section><section class="north-my-card"><h3>收入明细</h3>'+ (northIncomeEntries().length?northIncomeEntries().map(function(e){return '<div class="north-check-line"><span>'+esc(e.shopName||'店铺顾客订单')+'</span><b>¥'+money(e.amount/100)+'</b></div>';}).join(''):'<p class="north-merchant-empty">暂无顾客结算收入</p>')+'</section><section class="north-my-card"><h3>提现记录</h3>'+ (rows.length?rows.slice().reverse().map(function(w){return '<div class="north-check-line"><span>'+esc(fmtDT(w.time))+' · 已到微信零钱</span><b>¥'+money(w.amount/100)+'</b></div>';}).join(''):'<p class="north-merchant-empty">暂无提现记录</p>')+'</section></div></div>';}
  window.northIncomeWithdraw=function(){if(northSaving||northIncomeAvailable()<=0)return;openModal('<div class="north-flow north-merchant-form"><h3>提现到小手机微信</h3><p>可提现 ¥'+money(northIncomeAvailable()/100)+'</p><label>提现金额<input id="north_income_amount" type="number" step="0.01" min="0.01" max="'+northIncomeAvailable()/100+'" value="'+northIncomeAvailable()/100+'"></label><button class="btn p" onclick="northIncomePrepareWithdraw()">确认提现</button><button class="btn g" onclick="closeModal()">取消</button></div>');};
  window.northIncomePrepareWithdraw=function(){var input=document.getElementById('north_income_amount'),amount=input&&northMerchantMoney(input.value,false);if(!amount||amount>northIncomeAvailable()){toast('提现金额超过可提现收入');return;}northIncomeTransfer={kind:'income-withdraw',account:actId(),token:uid(),subtotal:amount};northPinEntry={account:actId(),token:northIncomeTransfer.token,value:'',busy:false};northPasswordPage();};
  async function northFinalizeIncomeWithdrawal(){var draft=northIncomeTransfer;if(northSaving||!draft||!draft.authorized||draft.account!==actId()||draft.subtotal>northIncomeAvailable()||northIncomeData().withdrawals.some(function(w){return w.id===draft.token;}))return;draft.authorized=false;var account=actId(),state=S,data=northIncomeData(),left=draft.subtotal,parts=[];for(var e of northIncomeEntries()){var amount=Math.min(left,Math.max(0,e.amount-(e.withdrawn||0)));if(amount){parts.push({entry:e,amount:amount});left-=amount;}if(!left)break;}if(left)return;var receipt={id:draft.token,account:account,amount:draft.subtotal,time:Date.now(),allocations:parts.map(function(p){return {entryId:p.entry.id,amount:p.amount};})};var ok=await northCommit(function(){parts.forEach(function(p){p.entry.withdrawn=(p.entry.withdrawn||0)+p.amount;});data.withdrawals.push(receipt);var undo=northBill('in',draft.subtotal,'店铺收入提现到微信',draft.token,account,state);return function(){undo();parts.forEach(function(p){p.entry.withdrawn-=p.amount;});var i=data.withdrawals.indexOf(receipt);if(i>=0)data.withdrawals.splice(i,1);};});if(ok&&account===actId()){northIncomeTransfer=null;northPinEntry=null;closeModal();render();toast('收入已提现到微信零钱');}}

  window.NorthCommercePayment.messageText=function(m){var r=northPayRequests().find(function(r){return r.id===m.northRequestId&&r.account===actId();});if(!r||r.status!=='pending')return '[这笔外卖代付请求已经处理或失效，不要再次支付。]';return '[我在'+(m.shop||'模拟外卖商铺')+'想买「'+m.name+'」，实付¥'+money(m.price)+'，请你代付。请求编号 '+r.id+'。你可以按人设同意或拒绝；同意时单独一行输出[外卖代付|'+r.id+'|同意]，拒绝时输出[外卖代付|'+r.id+'|拒绝]。必须使用这次请求编号，不要用旧代付成功标签。系统核验成功后才从你的模拟钱包扣款并下单；余额不足或请求失效不会扣款，也不要假称已支付。]';};

  window.NorthCommercePayment.roleSystemInstructions=function(id){var rows=S.food&&S.food.north&&S.food.north.payRequests||[],r=rows.slice().reverse().find(function(r){return r.account===actId()&&r.roleId===id&&r.status==='pending'&&r.expiresAt>Date.now();});if(!r)return '';return '\n\n# 当前外卖代付专用规则\n当前账号的模拟外卖请求编号是 '+r.id+'，金额¥'+money(r.draft.expectedTotal/100)+'。只有这笔请求使用[外卖代付|'+r.id+'|同意]或[外卖代付|'+r.id+'|拒绝]，不要写旧[代付成功]来处理它。你可以按人设拒绝，不能在系统核验前声称实际已经支付。其它普通商城和旅行卡片继续遵守其原规则。';};
  window.northMerchantClearSelection=function(group){if(!northMerchantActive()||!northMerchantLineDraft)return;var product=northMerchantView.draft.products.find(function(p){return p.id===northMerchantLineDraft.id;}),g=product&&product.specGroups.find(function(g){return g.id===group;});if(!g||g.required)return;document.querySelectorAll('.north-custom-option input[data-group="'+group+'"]').forEach(function(input){input.checked=false;});northMerchantLineDraft.selections[group]=[];northMerchantSpecPrice();};

