  async function northExpireFootprints(){if(northSaving)return false;var personal=S.food&&S.food.north&&S.food.north.personal;if(!personal)return false;var changes=Object.keys(personal).map(function(key){var row=personal[key],old=row.visits||[],fresh=northRecentVisits(old);return {row:row,old:old,fresh:fresh};}).filter(function(x){return x.old.length!==x.fresh.length;});if(!changes.length)return true;return northCommit(function(){changes.forEach(function(x){x.row.visits=x.fresh;});return function(){changes.forEach(function(x){x.row.visits=x.old;});};});}
