  function northFavoriteLabel(kind,source,id){var e=northCatalogEntry(kind,source,id);return e&&northPersonalData().favorites.some(function(x){return x.key===e.key;})?'★ 已收藏':'☆ 收藏';}
  function northFavoriteButton(kind,source,id){var entry=northCatalogEntry(kind,source,id),on=!!(entry&&northPersonalData().favorites.some(function(x){return x.key===entry.key;})),iconOnly=kind==='store';return '<button class="north-save-favorite north-star-favorite '+(iconOnly?'north-icon-only ':'')+(on?'on':'')+'" data-favorite-kind="'+kind+'" data-favorite-key="'+encodeURIComponent(entry?entry.key:'')+'" aria-label="'+(on?'取消收藏':'收藏')+(iconOnly?'店铺':'商品')+'" aria-pressed="'+on+'" onclick="event.stopPropagation();northFavorite(\''+kind+'\',\''+source+'\',\''+id+'\')">'+northFavoriteStar(on)+(iconOnly?'':'<span>'+(on?'已收藏':'收藏')+'</span>')+'</button>';}
  window.northFavorite=async function(kind,source,id){if(deliveryRealEnabled()&&source!=='cloud'||northSaving)return;var entry=northCatalogEntry(kind,source,id);if(!entry)return;var account=actId(),data=northPersonalData(),previous=data.favorites.slice(),found=data.favorites.find(function(x){return x.key===entry.key;});if(!found&&data.favorites.length>=80){toast('最多保存80项收藏，请先整理');return;}var ok=await northCommit(function(){if(found)data.favorites=data.favorites.filter(function(x){return x!==found;});else data.favorites.unshift(Object.assign(entry,{id:uid(),at:Date.now()}));return function(){data.favorites=previous;};});if(ok&&actId()===account){document.querySelectorAll('.north-save-favorite[data-favorite-key]').forEach(function(b){if(b.dataset.favoriteKey===encodeURIComponent(entry.key))northFavoritePaint(b,!found);});toast(found?'已取消收藏':'已收藏');}};
