  window.northPersonalSelect=function(id){if(!northPersonalActive())return;var v=northPersonalView,i=v.selected.indexOf(id);if(i<0)v.selected.push(id);else v.selected.splice(i,1);document.querySelectorAll('[data-personal-id]').forEach(function(el){var selected=v.selected.includes(el.dataset.personalId);el.classList.toggle('selected',selected);var mark=el.querySelector('.north-collection-open i,.north-address-edit');if(mark)mark.textContent=selected?'☑':'□';});var b=document.querySelector('.north-personal-delete');if(b)b.disabled=!v.selected.length;};
  window.northPersonalDelete=async function(){if(!northPersonalActive()||northSaving)return;var v=northPersonalView,account=actId(),d=northPersonalData(),field=v.page==='addresses'?'addresses':v.tab,old=d[field].slice(),oldId=d.selectedAddress,oldAddress=northData().addresses&&northData().addresses[account];if(!v.selected.length)return;var ok=await northCommit(function(){d[field]=d[field].filter(function(e){return !v.selected.includes(e.id);});if(field==='addresses'&&!d.addresses.some(function(e){return e.id===d.selectedAddress;})){d.selectedAddress=d.addresses[0]&&d.addresses[0].id||'';northAddressSync();}return function(){d[field]=old;d.selectedAddress=oldId;if(oldAddress)northData().addresses[account]=oldAddress;else if(northData().addresses)delete northData().addresses[account];};});if(ok&&actId()===account&&northPersonalView===v){v.selected=[];render();}};
  window.northCollectionOpen=function(id){if(!northPersonalActive())return;var v=northPersonalView,e=northPersonalData()[v.tab].find(function(e){return e.id===id;});if(!e)return;if(v.editing){northPersonalSelect(id);return;}if(e.source==='cloud'){northPersonalView=null;northMarketOpen(e.merchantId).then(function(){if(e.kind==='product'&&northMarketView&&northMarketView.id===e.merchantId)northMarketSpecs(e.productId);});return;}if(e.source==='north'){northPersonalView=null;northOpen();if(e.kind==='product'){var i=northMenu.findIndex(function(p){return p.id===e.productId;});if(i>=0)northSpecs(i);}return;}if(e.source==='custom'){var shop=northMerchantSaved();if(!shop||shop.id!==e.merchantId||shop.status!=='open'){toast('店铺已下架或不在当前账号');return;}if(e.kind==='product'&&!shop.products.some(function(p){return p.id===e.productId&&p.available;})){toast('商品已下架，仍可取消收藏');return;}northPersonalView=null;northMerchantPreview();if(e.kind==='product')northMerchantSpecs(e.productId);return;}northPersonalView=null;northBack();S.food.results=JSON.parse(JSON.stringify(e.kind==='store'&&e.snapshots?e.snapshots:[e.snapshot]));render();northVisit(e.kind,'model',0);if(e.kind==='product')foodBuy(0);else{var q=e.snapshot&&e.snapshot._northQuery||e.shop;S.food.q=q;S.food.results.forEach(function(p){p._northAccount=actId();p._northSource='ai';p._northQuery=q;if(!p._northResultId)p._northResultId=uid();});northAIShopOpen(0);}};
