  function northCollectionHTML(){var v=northPersonalView,d=northPersonalData(),rows=(v.tab==='visits'?northRecentVisits(d.visits):d.favorites).filter(function(e){return e.kind===v.kind;}),day='';return northPersonalHeader('<button class="'+(v.tab==='favorites'?'on':'')+'" onclick="northCollectionTab(\'favorites\')">收藏</button><button class="'+(v.tab==='visits'?'on':'')+'" onclick="northCollectionTab(\'visits\')">足迹</button>','<button onclick="northPersonalEditMode()">'+(v.editing?'完成':'编辑')+'</button>')+'<div class="north-personal-tabs">'+[['store','店铺'],['product','商品']].map(function(a){return '<button class="'+(v.kind===a[0]?'on':'')+'" onclick="northCollectionKind(\''+a[0]+'\')">'+a[1]+'（'+(v.tab==='visits'?northRecentVisits(d.visits):d.favorites).filter(function(e){return e.kind===a[0];}).length+'）</button>';}).join('')+'</div><div class="north-personal-scroll">'+(rows.length?rows.map(function(e){if(e.source==='custom'&&e.kind==='product'){var currentShop=northMerchantSaved(),live=currentShop&&currentShop.id===e.merchantId&&currentShop.products.find(function(p){return p.id===e.productId;});if(live)e=Object.assign({},e,{name:live.name,shop:currentShop.name,imageUrl:live.image,price:live.price/100,signature:live.signature===true});}var date=new Date(e.at).toLocaleDateString('zh-CN',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit'}),heading=v.tab==='visits'&&date!==day?'<div class="north-visit-date">'+date+'</div>':'';day=date;return heading+'<article class="north-collection-card '+(v.selected.includes(e.id)?'selected':'')+'" data-personal-id="'+e.id+'"><button class="north-collection-open" onclick="northCollectionOpen(\''+e.id+'\')"><span class="north-collection-cover">'+mtMedia(e)+'</span><span><b>'+northSignatureBadge(e.kind==='product'&&e.signature===true)+esc(e.name)+'</b><small>'+esc(e.kind==='product'?e.shop:'本机模拟商铺')+'</small>'+(e.kind==='product'?'<strong>¥'+money(e.price)+'</strong>':'')+'</span><i>'+(v.editing?(v.selected.includes(e.id)?'☑':'□'):'›')+'</i></button>'+(e.kind==='store'?'<div class="north-collection-products">'+e.products.map(function(p){return '<div><span>'+mtMedia(p)+'</span><small>'+northSignatureBadge(p.signature===true)+esc(p.name)+'</small><strong>¥'+money(p.price)+'</strong></div>';}).join('')+'</div>':'')+(v.tab==='visits'&&!v.editing?'<div class="north-favorite-strip"><button class="north-save-favorite" onclick="northCollectionFavorite(\''+e.id+'\')">'+(d.favorites.some(function(f){return f.key===e.key;})?'★ 已收藏':'☆ 收藏')+'</button></div>':'')+'</article>';}).join(''):'<div class="commerce-empty">'+(v.tab==='favorites'?'还没有收藏，打开店铺或商品后点收藏。':'还没有浏览足迹，打开店铺和商品后会记录。')+'</div>')+'</div>'+(v.editing?'<footer class="north-personal-footer"><button class="north-personal-delete" onclick="northPersonalDelete()" '+(!v.selected.length?'disabled':'')+'>删除选中记录</button></footer>':'');}
