  function northMyReviewsHTML(){var rows=northMyOrders().filter(function(o){return o.status==='completed'&&o.review;}),pending=northMyOrders().filter(function(o){return o.status==='completed'&&!o.review;}).length;return northPersonalHeader('我的评价')+'<div class="north-personal-scroll">'+(pending?'<button class="north-review-pending" onclick="northPendingReviews()">'+pending+' 笔已完成订单待评价<span>去评价 ›</span></button>':'')+(rows.length?rows.map(function(o){var r=o.review;return '<article class="north-own-review"><div class="north-own-review-head"><span><img src="assets/meituan-kangaroo.png" alt="评价头像"></span><div><button onclick="northOrder(\''+o.id+'\')">'+esc(o.shop)+' ›</button><small>商家：<em>'+('★'.repeat(r.rating))+'</em>　'+r.rating+'星'+(r.packagingRating?' · 包装'+r.packagingRating+'星':'')+(r.anonymous?' · 匿名':'')+'</small></div><time>'+esc(new Date(r.createdAt||o.receivedAt).toLocaleDateString('zh-CN',{timeZone:'Asia/Seoul'}))+'</time></div><p>'+esc(r.text)+'</p>'+northReviewAttachments(r,o.id)+'<small class="north-review-items">'+esc(o.items.map(function(p){return p.name;}).join('、'))+'</small>'+(r.followups||[]).map(function(f){return '<div class="north-review-followup"><small>追加评价 · '+esc(fmtDT(f.at))+'</small><p>'+esc(f.text)+'</p></div>';}).join('')+'<footer><button onclick="northWriteReview(\''+o.id+'\')">修改评价</button><button onclick="northReviewFollowup(\''+o.id+'\')">✎ 追评</button><button onclick="northReviewDeleteAsk(\''+o.id+'\')">删除</button></footer></article>';}).join(''):'<div class="commerce-empty">暂无已提交评价。'+(pending?'上方可以进入待评价订单。':'完成订单后可以评价。')+'</div>')+'</div>';}
  window.northReviewFollowup=function(id){var o=northFind(id);if(!northPersonalActive()||!o||!o.review)return;openModal('<div class="north-flow"><h3>追加评价</h3><textarea id="north_followup" maxlength="300" placeholder="补充这次购买的感受"></textarea><button class="btn p" onclick="northReviewFollowupSave(\''+id+'\')">保存追评</button><button class="btn g" onclick="closeModal()">取消</button></div>');};
