  window.northAddressSave=async function(){if(!northPersonalActive()||!northAddressEdit||northAddressEdit.account!==actId()||northSaving)return;var d=northPersonalData(),view=northPersonalView,a={id:northAddressEdit.id,address:document.getElementById('north_address_edit').value.trim(),receiver:document.getElementById('north_receiver_edit').value.trim(),phone:document.getElementById('north_phone_edit').value.trim(),tag:document.getElementById('north_tag_edit').value.trim()},account=actId();if(!a.address||!a.receiver){toast('请填写收货地址和收货人');return;}var old=d.addresses.slice(),selected=d.selectedAddress,previous=northData().addresses&&northData().addresses[account],index=d.addresses.findIndex(function(x){return x.id===a.id;});if(index<0&&d.addresses.length>=30){toast('最多保存30个地址');return;}var ok=await northCommit(function(){if(index>=0)d.addresses[index]=a;else d.addresses.push(a);if(!d.selectedAddress)d.selectedAddress=a.id;northAddressSync();return function(){d.addresses=old;d.selectedAddress=selected;if(previous)northData().addresses[account]=previous;else if(northData().addresses)delete northData().addresses[account];};});if(ok&&actId()===account&&northPersonalView===view){northAddressEdit=null;closeModal();render();}};
