  window.northSearchWord=function(index,history){if(!northPersonalActive())return;var words=history?northPersonalData().searches:northSearchSuggestions(),word=words[index];if(!word)return;document.getElementById('food_q').value=word;foodSearch();};
  window.northClearSearches=async function(){if(!northPersonalActive()||northSaving)return;var d=northPersonalData(),old=d.searches,account=actId(),ok=await northCommit(function(){d.searches=[];return function(){d.searches=old;};});if(ok&&actId()===account)render();};
  function northSearchHTML(){var v=northPersonalView;if(v.submitted)return northSearchResultPage();var d=northPersonalData(),words=northSearchSuggestions(),start=(v.batch*8)%words.length,shown=words.slice(start,start+12),q=v.query||'',matches=q?northMenu.filter(function(p){return (p.name+' '+northGroups[p.group]).includes(q);}):[];return '<header class="north-search-head"><button onclick="northPersonalBack()" aria-label="返回">'+mtGlyph('chevronLeft',25,'currentColor')+'</button><div class="mt-search"><input id="food_q" value="'+esc(q)+'" placeholder="搜店铺、商品或美食" onkeydown="if(event.key===\'Enter\')foodSearch()"><button onclick="foodSearch()" '+(_foodBusy?'disabled':'')+'>搜索</button></div></header><div class="north-personal-scroll north-search-scroll"><section><div class="north-search-section"><h3>历史搜索</h3><button onclick="northClearSearches()" aria-label="清空历史搜索">清空</button></div><div class="north-search-words">'+(d.searches.length?d.searches.map(function(w,i){return '<button onclick="northSearchWord('+i+',true)">'+esc(w)+'</button>';}).join(''):'<small>暂无搜索记录</small>')+'</div></section><section><div class="north-search-section"><h3>猜你想搜</h3><button onclick="northSearchBatch()">换一批 ↻</button></div><div class="north-search-words">'+shown.map(function(w,i){return '<button onclick="northSearchWord('+(start+i)+',false)">'+esc(w)+'</button>';}).join('')+'</div></section>'+northRecommendedShops()+'</div>';}
  window.northSearchProduct=function(id){var i=northMenu.findIndex(function(p){return p.id===id;});if(i<0)return;northPersonalView=null;northOpen();northSpecs(i);};
  window.northPlayRules=function(){northMarketEpoch++;northMarketView=null;northMarketBusy=false;northPersonalStart('rules');};
  function northPlayRulesHTML(){return northPersonalHeader('玩法规则')+'<div class="north-personal-scroll north-play-rules">'+[["先分清两种店","真人店铺是其他小手机用户创建、发布的店；AI店铺是模型模拟的店。这套真人店铺/AI店铺玩法里的商品、配送和金额都属于小手机模拟，不是真实送餐或人民币交易。"],["选商品与下单","进店选商品和规格，加入购物车后去结算。真人店铺按商家设置的起送价；AI店铺没有起送价。确认地址、配送时间和餐具，再选择付款方式。"],["钱包与情侣代付","每个符合授权条件的账号首次可领取500云端额度，只领一次，不限制以后赚取的余额。云端额度用于真人店交易；情侣云银行卡需要手动充值。只有当前情侣可以代付真人订单，真人店不支持亲属卡。本机模拟订单使用本机资金，两边分开。"],["神券","神券用云端钱包购买，付款成功后到账，可用于真人店铺。31天有效，每24小时最多买1包、膨胀1次，有效未用券最多20张。每单1张，商品及小料达到门槛可用，配送费不抵扣。膨胀提高优惠和门槛，不延长时间；券包不退。"],["角色自主点单","告诉当前情侣想吃的品类、口味和规格，不必知道商品全名；角色也可主动挑选。先搜索真人在售菜单，再由模型筛选真实商品和选项，后台核验库存、起送价、价格与余额。只有需要达到起送价时才允许增加同店商品或份数，成功卡片会明确说明。角色可使用你的可用云券，系统选符合门槛且优惠最大的单张券，同优惠先用更早到期的券；不会为了用券多买。实付从角色手动充值的云银行卡扣除，商品、数量、规格和已减金额可在详情核对。"],["点单结果与失败","筛选会额外调用角色当前配置的模型，最多3次，可能增加等待时间和模型费用。付款成功回执立即生成简短卡片，其他商品可展开，完整费用在详情查看，不将聊天承诺当成付款。找不到符合口味的真人商品或角色云余额没有可用额度或确实无法购买时才转模拟；网络或模型失败不假装没有商品、不扣款。付款结果未知先查原订单，不重复支付；实际扣款成功后即使最后模型回复失败仍保留订单。自己的店铺不作为角色刷单对象。"],["开店与补货","在我的功能里开店，可上传图片、自定商品分组、规格和招牌标签，并选分类标签方便关键词搜索。同一家店可保存通用规格模板，新商品沿用，已有商品确认后一键套用；各店独立，特殊商品可单独改。编辑后先保存再更新发布，顾客看到的是已发布菜单。第一家免费，第二家创业费200，第三家400，最多3家；创业费需要足够的已实现利润和未转出的店铺收入。补货按商品基础售价40%取整付进货成本，最低0.01；支持一键整批补货，先看总价再支付，任何一项失败整批不扣款、不入库；售罄变灰，补货后恢复，未售库存可按原成本退回原资金来源。"],["收入怎么用","顾客订单完成后才结算店铺收入。收入可转到本人的美团云端余额，或当前情侣云银行卡，不能兑换人民币，也不能转到本机微信零钱。已实现净利润会扣除已售商品进货成本与创业费；库存不是可直接花的余额。"],["拼单、预约与退款","拼单限两位已确认的真人好友，最终金额含配送费平分，双方分别确认付款，付齐才创建配送订单。30分钟未付齐或取消，已付金额原路退回。预约可选30分钟后至未来6天；真人新订单按商家设置的10至120分钟（默认30分钟）自动推进，到预计时间完成、结算收入并开放评价；预约不早于所选时间，拼单付齐后计时。云端每分钟处理一次，可能稍晚于预计时间，关App不重置。旧订单保留手动配送；AI订单按本机所选时间推进，关App期间不运行本机定时；普通订单按允许的状态取消，已完成订单不能退款。取消时未过期的已用券退回。"],["评价与日常功能","已完成订单才能评价，一单一条，可附图片、可修改或追评；真人评分按有效顾客评价统计，不填随机评分；商家每条评价只回复一次，回复在我的评价里查看，有未读红点。收藏星星点亮变黄；足迹保留30天，打开或前台检查时清掉过期记录。支付密码默认00000，在我的功能→设置修改；本机与云端密码分开。跑腿暂未开放，点击显示开发中。"]].map(function(section){return '<section class="north-my-card" style="margin:12px;line-height:1.8"><h3>'+esc(section[0])+'</h3><p>'+esc(section[1])+'</p></section>';}).join('')+'</div>';}
  function northPersonalRender(){var v=northPersonalView;return '<div class="mt-home north-personal-page">'+(v.page==='rules'?northPlayRulesHTML():v.page==='collections'?northCollectionHTML():v.page==='reviews'?northMyReviewsHTML():v.page==='addresses'?northAddressesHTML():v.page==='review-write'?northReviewPage():v.page==='ai-shop'?northAIShopPage():northSearchHTML())+'</div>';}
  var northPersonalBaseSearch=window.foodSearch;
  window.foodSearch=async function(){if(deliveryRealEnabled())return northPersonalBaseSearch.apply(this,arguments);if(_foodBusy||northSaving)return;var input=document.getElementById('food_q'),q=input&&input.value.trim().slice(0,60);if(!q){northSearchPage();return;}var account=actId(),data=northPersonalData(),old=data.searches,ok=await northCommit(function(){data.searches=[q].concat(data.searches.filter(function(s){return s!==q;})).slice(0,20);return function(){data.searches=old;};});if(!ok||actId()!==account)return;var fixed=[northShopName,'奶茶','冰冰茶','咖啡','小料'].some(function(w){return w===q;})||northMenu.some(function(p){return p.name.includes(q);});if(fixed){S.food.q=q;northPersonalStart('search');northPersonalView.query=q;render();return;}northBack();var field=document.getElementById('food_q');if(field)field.value=q;return northPersonalBaseSearch.apply(this,arguments);};
  ['northMy','northBack','northOpen','northOrders','northOrder','northCouponsPage','northMerchantEditor','northMerchantPreview','northIncome'].forEach(function(name){var original=window[name];window[name]=function(){northPersonalView=null;return original.apply(this,arguments);};});
  var northVisitedOpen=window.northOpen;window.northOpen=function(){var result=northVisitedOpen.apply(this,arguments);northVisit('store','north','north');return result;};
  var northVisitedPreview=window.northMerchantPreview;window.northMerchantPreview=function(){var result=northVisitedPreview.apply(this,arguments);northVisit('store','custom','');return result;};
  var northVisitedSpecs=window.northSpecs;window.northSpecs=function(i){if(northMenu[i])northVisit('product','north',northMenu[i].id);return northVisitedSpecs.apply(this,arguments);};
  var northVisitedCustomSpecs=window.northMerchantSpecs;window.northMerchantSpecs=function(id){northVisit('product','custom',id);return northVisitedCustomSpecs.apply(this,arguments);};
  var northVisitedBuy=window.foodBuy;window.foodBuy=function(i){if(!deliveryRealEnabled()){northVisit('store','model',i);northVisit('product','model',i);}return northVisitedBuy.apply(this,arguments);};


  /* Audited simulated search and all self-order routes. Real platform remains separate. */
  var northSearchRun=null,northSimulationShop=null;
  function northLocalSearch(q){var key=String(q||'').trim().toLowerCase(),shop=northMerchantSaved(),fixed=!key||[northShopName,'奶茶','茶','饮品','甜点饮品','咖啡','冰冰茶','小料'].some(function(w){return w.toLowerCase().includes(key);})||northMenu.some(function(p){return(p.name+' '+p.desc).toLowerCase().includes(key);}),custom=shop&&shop.status==='open'&&(!key||[shop.name,shop.category].concat(shop.tags,shop.products.filter(function(p){return p.available;}).map(function(p){return p.name+' '+p.description;})).join(' ').toLowerCase().includes(key));return {fixed:fixed,custom:!!custom};}
  function northExactLocalSearch(q){var shop=northMerchantSaved(),key=String(q).toLowerCase();return key===northShopName.toLowerCase()||northMenu.some(function(p){return p.name.toLowerCase()===key;})||shop&&shop.status==='open'&&(shop.name.toLowerCase()===key||shop.products.some(function(p){return p.available&&p.name.toLowerCase()===key;}));}
  function northAIShopGroups(rows){var groups=[];(rows||[]).forEach(function(p,i){if(p._northAccount&&p._northAccount!==actId())return;var g=groups.find(function(g){return g.name===p.shop;});if(!g){g={name:p.shop,items:[]};groups.push(g);}g.items.push({product:p,index:(S.food.results||[]).indexOf(p)});});return groups;}
  function northAIShopHTML(groups){return groups.map(function(g,i){return '<article class="north-collection-card north-ai-store north-real-nearby"><button class="north-collection-open" onclick="northAIShopOpen('+i+')"><span class="north-collection-cover">'+mtMedia(g.items[0].product)+'</span><span><b>'+esc(g.name)+'</b><small class="north-ai-source">AI 模拟商家 · 虚拟钱包结算</small>'+northShopFigures('ai',g.name)+'</span><i>›</i></button>'+northFavoriteButton('store','model',g.items[0].index)+'</article>';}).join('');}
  window.northAIShopOpen=function(index){if(deliveryRealEnabled())return;var groups=northAIShopGroups((S.food.results||[]).filter(function(p){return p._northQuery===S.food.q;})),g=groups[index];if(!g)return;northPersonalStart('ai-shop');northSimulationShop={account:actId(),name:g.name,items:JSON.parse(JSON.stringify(g.items.map(function(row){return row.product;})))};northVisit('store','model',g.items[0].index);render();};
  function northAIShopPage(){var shop=northSimulationShop;if(!shop||shop.account!==actId())return northPersonalHeader('AI 模拟商铺')+'<div class="commerce-empty">商铺结果已变化，请重新搜索。</div>';var firstIndex=(S.food.results||[]).findIndex(function(p){return p._northResultId===shop.items[0]._northResultId;}),rows=northSimulationCartRows().filter(function(p){return p._northGeneric&&p.shop===shop.name;}),sum=rows.reduce(function(n,p){return n+northCents(p.price);},0),groups=[];shop.items.forEach(function(p){var name=p.category||p.group||'本店商品';if(!groups.includes(name))groups.push(name);});var selected=shop.group||'',shown=shop.items.filter(function(p){return !selected||(p.category||p.group||'本店商品')===selected;});return '<div class="north-market-store north-store north-ai-order-store">'+northPersonalHeader(esc(shop.name),firstIndex>=0?northFavoriteButton('store','model',firstIndex):'')+'<header class="north-info"><span class="north-market-cover">'+mtMedia(shop.items[0])+'</span><div><h2>'+esc(shop.name)+'</h2>'+northShopFigures('ai',shop.name)+'</div></header><div class="north-delivery"><b>外送</b><span>无起送价 · 配送 ¥1.90</span></div><div class="north-store-note">AI 模拟商家，使用本机余额<span>模拟店铺</span></div><div class="north-tabs"><button class="'+(!shop.reviews?'on':'')+'" onclick="northAIShopTab(false)">点菜</button><button class="'+(shop.reviews?'on':'')+'" onclick="northAIShopTab(true)">评价</button></div><div class="north-panel">'+(shop.reviews?northAIStoreReviews(shop.name):(!selected?'<div class="north-hero-row">'+shop.items.slice(0,3).map(function(p){var index=(S.food.results||[]).findIndex(function(x){return x._northResultId===p._northResultId;});return '<button onclick="northAISpecs('+index+')" '+(index<0?'disabled':'')+'><b>'+esc(p.name)+'</b><small>'+esc(p.desc)+'</small><span>'+mtMedia(p)+'</span></button>';}).join('')+'</div><div class="north-tip">温馨提示：请适量点餐</div>':'')+'<div class="north-menu-layout"><aside><button class="'+(!selected?'on':'')+'" onclick="northAIShopGroup(\'\')">全部商品</button>'+groups.map(function(g){return '<button class="'+(selected===g?'on':'')+'" onclick="northAIShopGroup('+northMarketArgument(g)+')">'+esc(g)+'</button>';}).join('')+'</aside><div class="north-drinks">'+shown.map(function(p){var index=(S.food.results||[]).findIndex(function(x){return x._northResultId&&x._northResultId===p._northResultId;});return '<article class="north-drink"><div class="north-drink-image">'+mtMedia(p)+'</div><div class="north-drink-copy"><b>'+esc(p.name)+'</b><small>'+esc(p.desc)+'</small><div class="north-drink-price"><span>¥'+money(p.price)+'</span><button onclick="northAISpecs('+index+')" '+(index<0?'disabled':'')+'>选规格</button></div></div></article>';}).join('')+'</div></div>')+'</div><footer class="north-footer north-cartbar"><button class="north-cart-detail" onclick="northSimulationCart()">'+northCartMascot(rows.reduce(function(n,p){return n+(p.quantity||1);},0))+'<span><b>¥'+money(sum/100)+'</b><small>配送 ¥1.90 · 明细⌃</small></span></button><button class="north-checkout-button" onclick="northAIShopCheckout()" '+(!rows.length?'disabled':'')+'>'+(rows.length?'去结算':'选择商品')+'</button></footer></div>';}
  window.northAIShopGroup=function(name){var shop=northSimulationShop;if(!shop||shop.account!==actId())return;if(name&&!shop.items.some(function(p){return (p.category||p.group||'本店商品')===name;}))return;shop.group=name;render();};
  window.northAIShopTab=function(reviews){if(!northSimulationShop||northSimulationShop.account!==actId())return;northSimulationShop.reviews=!!reviews;render();};
  window.northAIShopCheckout=function(){var shop=northSimulationShop;if(!shop||shop.account!==actId()||deliveryRealEnabled()||northSaving)return;var rows=northSimulationCartRows().filter(function(p){return p._northGeneric&&p.shop===shop.name;});if(!rows.length){toast('请先选择商品');return;}northCheckout(rows,true);};
  window.northSearchMoreAI=function(){if(!northPersonalActive())return;var input=document.getElementById('food_q');if(input&&!input.value.trim())input.value=northPersonalView.query||'';foodSearch(true);};
  window.northRemoteShopInfo=function(){northMarketList(S.food.q||'');};
  window.foodSearch=async function(forceAI){
    if(deliveryRealEnabled())return northPersonalBaseSearch.apply(this,arguments);
    if(_foodBusy||northSaving)return;
    var input=document.getElementById('food_q'),q=input&&input.value.trim().slice(0,60);if(!q){northSearchPage();return;}
    var state=S,account=actId(),data=northPersonalData(),old=data.searches,ok=await northCommit(function(){data.searches=[q].concat(data.searches.filter(function(s){return s!==q;})).slice(0,20);return function(){data.searches=old;};});
    if(!ok||S!==state||actId()!==account||deliveryRealEnabled())return;
    S.food.q=q;northPersonalStart('search');var view=northPersonalView;view.query=q;view.submitted=true;view.aiError='';
    var remote=await northMarketSearchStores(q,view);if(S!==state||actId()!==account||northPersonalView!==view)return;if(remote.length&&!forceAI){view.localOnly=true;render();return;}
    if(!forceAI&&northExactLocalSearch(q)){view.localOnly=true;render();return;}
    var request={id:uid(),account:account,state:state,view:view};northSearchRun=request;_foodBusy=true;render();
    try{
      var rows=await aiGen([{role:'system',content:'你在小手机内创建AI模拟外卖商家，不是查询真实商家。生成6个相关商品，分属至少3个不同的模拟商铺。可按用户店名生成同风格的模拟店，但不要宣称是真人店主或平台真实分店。每行格式：餐品名:::正数价格数字:::模拟店铺名:::一句描述:::相关emoji。价格0.01至9999.99，不含币种、负号、区间。不要编造销量评分距离优惠。药店用品仅生成模拟购物商品，不诊断、不提供用药或剂量建议。不要其它文字。'},{role:'user',content:'模拟搜索：'+q}],{max:1000,aux:true},looseLines);
      if(northSearchRun!==request||S!==state||actId()!==account||deliveryRealEnabled()||northPersonalView!==view||typeof cur==='function'&&cur().p!=='food')return;
      var valid=(Array.isArray(rows)?rows:[]).map(function(row){if(!Array.isArray(row)||row.length<3)return null;var raw=String(row&&row[1]||'').trim(),price=/^\d+(?:\.\d{1,2})?$/.test(raw)?Number(raw):NaN,name=String(row&&row[0]||'').trim(),shop=String(row&&row[2]||'').trim();if(!name||!shop||!Number.isFinite(price)||price<.01||price>9999.99)return null;return {name:name.slice(0,80),price:Math.round(price*100)/100,shop:shop.slice(0,60),desc:String(row[3]||'').slice(0,180),emoji:String(row[4]||'🍱').slice(0,8),_northSource:'ai',_northAccount:account,_northQuery:q,_northResultId:uid()};}).filter(Boolean).slice(0,12);
      S.food.results=valid;if(!valid.length)view.aiError='没有生成有效商品，请重试或换个关键词。';save();
    }catch(e){if(northSearchRun===request&&S===state&&actId()===account&&northPersonalView===view)view.aiError='AI 模拟搜索失败，检查模型配置后可重试。';}
    finally{if(northSearchRun===request){northSearchRun=null;_foodBusy=false;if(S===state&&actId()===account&&!deliveryRealEnabled())render();}}
  };
  function northGenericLine(product){if(!product||product.offerId||product._northAccount&&product._northAccount!==actId()||!Number.isFinite(+product.price)||+product.price<=0||+product.price>9999.99)return null;return {name:product.name||'餐品',price:+product.price,quantity:1,shop:product.merchant||product.shop||'AI模拟商铺',imageUrl:product.imageUrl||product.img||product.src||'',_northSource:'ai',_northGeneric:true,_northAccount:actId(),_northRow:uid()};}
  var northAuditedFoodBuy=window.foodBuy;
  window.foodBuy=function(index){if(deliveryRealEnabled())return northAuditedFoodBuy.apply(this,arguments);northVisit('store','model',index);northVisit('product','model',index);return northGenericCheckout(index);};
  window.northGenericCheckout=function(index,mode){if(deliveryRealEnabled()||northSaving)return;var item=northGenericLine((S.food.results||[])[index]);if(!item)return;northCheckout([item],true);if(northCheckoutDraft&&mode){northCheckoutDraft.pendingFunding=mode;northPaymentMethods(mode);}};
  var northAuditedFoodCart=window.foodCart;
  window.foodCart=async function(index){if(deliveryRealEnabled())return northAuditedFoodCart.apply(this,arguments);if(northSaving)return;var product=(S.food.results||[])[index],item=northGenericLine(product);if(!item)return;var account=actId(),cart=S.food.cart=S.food.cart||[],ok=await northCommit(function(){cart.push(item);return function(){var i=cart.indexOf(item);if(i>=0)cart.splice(i,1);};});if(ok&&actId()===account){northVisit('product','model',index);mtPaintCart();toast('已加入模拟购物车');}};
  function northSimulationCartRows(){return(S.food.cart||[]).filter(function(p){return p._northAccount===actId()&&!p.offerId&&(p._northGeneric||p._northSku||p._northMerchant);});}
  function northSimulationShopKey(p){return p._northMerchant?'custom:'+p._northMerchant:p._northSku?'north':JSON.stringify(['ai',p.shop]);}
