  function northReviewStarSVG(on){return '<svg viewBox="0 0 24 24" width="25" height="25" fill="'+(on?'#ffdf22':'#e4e4e4')+'" aria-hidden="true"><path d="m12 2.5 3 6.1 6.8 1-4.9 4.8 1.2 6.8-6.1-3.2-6.1 3.2 1.2-6.8-4.9-4.8 6.8-1z"/></svg>';}
