  function northReviewRatingText(n){return ['未评分','非常差','较差','一般','满意','非常满意'][n||0];}
  window.northWriteReview=function(id){if(deliveryRealEnabled()||northSaving)return;var o=northFind(id);if(!o||o.status!=='completed'){toast('只有已完成订单可以评价');return;}var r=o.review||{},fromMy=northPersonalActive()&&northPersonalView.page==='reviews',account=actId();northReviewEditor={id:id,account:account,returnToMy:fromMy,nonce:uid(),rating:r.rating||null,packagingRating:r.packagingRating||null,text:r.text||'',textLimit:Math.max(200,(r.text||'').length),anonymous:o.review?!!r.anonymous:true,images:(r.images||[]).slice(),courier:r.courier?JSON.parse(JSON.stringify(r.courier)):{satisfied:null,tags:[]},stagedImages:[],uploading:false,dirty:false,previousReference:o.review||null};northPersonalStart('review-write');render();};
  window.northReviewChoose=function(field,n){if(!northReviewActive()||northSaving||!['rating','packagingRating'].includes(field)||!Number.isInteger(n)||n<1||n>5)return;var e=northReviewEditor;e[field]=n;e.dirty=true;var row=document.querySelector('[data-rating="'+field+'"]');if(row){row.querySelectorAll('button[data-star]').forEach(function(b){b.innerHTML=northReviewStarSVG(n>=+b.dataset.star);});row.querySelector('span').textContent=northReviewRatingText(n);}var hidden=document.getElementById(field==='rating'?'north_review_rating':'north_review_packaging');if(hidden)hidden.value=n;northReviewPublishState();};
