  window.northReviewUpload=async function(input){if(!northReviewActive()||northReviewEditor.uploading||northSaving)return;var e=northReviewEditor,account=actId(),files=Array.from(input.files||[]);if(!files.length)return;if(e.images.length+files.length>6||files.some(function(f){return !/^image\//.test(f.type)||f.size>20*1024*1024;})){toast('最多6张，每张请选择20MB以内的图片');input.value='';return;}e.uploading=true;input.disabled=true;northReviewPublishState();try{for(var file of files){var key='north_review_'+account.replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+uid(),fresh=true,raw=await compress(file,800,.8);if(raw.length>240000)raw=await compress(file,640,.72);if(raw.length>260000||!/^data:image\//.test(raw)||!await viewerImageDecoded(raw))throw Error('图片无法读取');if(northReviewEditor!==e||account!==actId()||!northReviewActive())return;var cached=_imgRev.get(raw);if(cached&&_imgReady.has(cached)&&(e.images.includes('idb:'+cached)||(S.food.north.orders||[]).some(function(o){return o.review&&(o.review.images||[]).some(function(ref){return ref==='idb:'+cached||ref===raw;});}))){key=cached;fresh=false;}else await imgPut(key,raw);if(northReviewEditor!==e||account!==actId()||!northReviewActive()){if(fresh)await imgDel(key);return;}if(await imgGet(key)!==raw){if(fresh)await imgDel(key);throw Error('图片没有保存成功');}_imgCache[key]=raw;_imgRev.set(raw,key);_imgReady.add(key);if(fresh)e.stagedImages.push(key);var ref='idb:'+key;if(!e.images.includes(ref))e.images.push(ref);e.dirty=true;}var region=document.querySelector('.north-review-image-region');if(region&&northReviewEditor===e)region.innerHTML=northReviewImagesHTML();toast('图片已添加，发布后保留');}catch(error){toast('图片添加失败，已有图片保留');}finally{e.uploading=false;input.disabled=false;input.value='';if(northReviewEditor===e){var region=document.querySelector('.north-review-image-region');if(region)region.innerHTML=northReviewImagesHTML();northReviewPublishState();}}};
