  function northReviewStopVoice(){if(northReviewSpeech){try{northReviewSpeech.abort();}catch(_){}northReviewSpeech=null;}}
  window.northReviewVoice=function(){if(!northReviewActive())return;if(northReviewSpeech){northReviewStopVoice();return;}var e=northReviewEditor,sr=typeof makeSR==='function'?makeSR('zh'):null;if(!sr){toast('当前环境不支持语音输入');return;}northReviewSpeech=sr;sr.interimResults=false;sr.continuous=false;sr.onresult=function(event){if(northReviewEditor!==e||e.account!==actId()||!northReviewActive()){northReviewStopVoice();return;}var text=Array.from(event.results||[]).filter(function(r){return r.isFinal;}).map(function(r){return r[0]&&r[0].transcript||'';}).join('');if(!text)return;e.text=(e.text+text).slice(0,e.textLimit);var field=document.getElementById('north_review_text');if(field)field.value=e.text;northReviewText(e.text);};sr.onerror=function(){toast('语音输入未完成，可以继续打字');northReviewStopVoice();};sr.onend=function(){if(northReviewSpeech===sr)northReviewSpeech=null;};try{sr.start();toast('正在听，结束后文字会填入评价');}catch(_){northReviewStopVoice();toast('无法启动语音输入，请检查权限');}};
  window.northReviewBack=function(){if(!northReviewActive())return;var e=northReviewEditor;if(e.uploading){toast('图片正在保存，请稍等');return;}if(e.dirty){openModal('<div class="north-flow"><h3>评价还没有发布</h3><button class="btn p" onclick="closeModal()">继续编辑</button><button class="btn g" onclick="northReviewLeave()">放弃本次修改</button></div>');return;}northReviewLeave();};
  window.northReviewLeave=async function(){var e=northReviewEditor;if(!e||e.account!==actId())return;northReviewStopVoice();northReviewEditor=null;northPersonalView=null;closeModal();await northReviewCleanup(e);if(e.account!==actId())return;if(e.returnToMy)northMyReviews();else northOrder(e.id);};
  function northReviewAttachments(r,id){return r.images&&r.images.length?'<div class="north-published-images">'+r.images.map(function(ref,i){return '<button onclick="northReviewImageOpen(\''+id+'\','+i+')" aria-label="查看评价图片">'+mtMedia({name:'评价图片',imageUrl:ref})+'</button>';}).join('')+'</div>':'';}
  window.northReviewImageOpen=function(id,index){var o=northFind(id),ref=o&&o.review&&o.review.images&&o.review.images[index];if(!ref)return;openModal('<div class="north-flow"><h3>评价图片</h3><div class="north-review-full-image">'+mtMedia({name:'评价图片',imageUrl:ref})+'</div><button class="btn g" onclick="closeModal()">关闭</button></div>');};

  function northPublishedReviewRows(rows){return rows.map(function(o){var r=o.review;return '<article class="north-review north-personal-review" data-review-order="'+o.id+'"><div class="north-review-head"><img src="assets/meituan-kangaroo.png" alt="评价头像"><div><b>'+esc(r.name||'顾客')+' · 我的购买评价</b><small>商品 <em>'+('★'.repeat(r.rating))+'</em> '+r.rating+'星'+(r.packagingRating?' · 包装'+r.packagingRating+'星':'')+'</small></div><time>'+esc(fmtDT(r.updatedAt||r.createdAt))+'</time></div>'+(r.text?'<p>'+esc(r.text)+'</p>':'')+northReviewAttachments(r,o.id)+'<small class="north-review-items">'+esc(o.items.map(function(p){return p.name;}).join('、'))+'</small>'+(r.followups||[]).map(function(f){return '<div class="north-review-followup"><small>追加评价 · '+esc(fmtDT(f.at))+'</small><p>'+esc(f.text)+'</p></div>';}).join('')+'<button class="north-review-product" onclick="northOrder(\''+o.id+'\')">查看对应订单 ›</button></article>';}).join('');}
  function northAIStoreReviews(name){var rows=northMyOrders().filter(function(o){return !o.merchantId&&o.shop===name&&o.status==='completed'&&o.review&&Array.isArray(o.items)&&o.items.some(function(p){return p._northGeneric;})&&!o.items.some(function(p){return p._northSku;});});return rows.length?northPublishedReviewRows(rows):'<p class="north-merchant-empty">还没有已完成订单的评价。</p>';}

