  function northShopDisplay(kind,id,address){var key=String(kind)+'|'+String(id),month=typeof curMonth==='function'?curMonth():new Date().toISOString().slice(0,7),saved=S.food&&S.food.north&&S.food.north.addresses&&S.food.north.addresses[actId()],place=address==null?saved&&saved.address||'小手机 · 我的家':String(address),distance=(4+seedOf('distance|'+key+'|'+String(place).replace(/\s+/g,''))%61)/10,prep=4+seedOf('prep|'+key)%12;return {distance:distance,monthlySales:80+seedOf('sales|'+key+'|'+month)%5801,etaMinutes:12+Math.ceil(distance*4)+prep};}
